window.KG_CALC = [{"set": 1, "date": "2026-09-28", "session": "day", "title": "资料分析速算训练 · 第 1 批（估算 / 直除 / 增长率 / 比重）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "计算 4823 ÷ 617，结果最接近下列哪一项？", "options": ["5.8", "6.8", "7.8", "8.8"], "answer": ["C"], "method": "直除定首位：617×7＝4319，4823－4319＝504，余数 504 小于 617 且接近 617 的 0.8 倍 → 商约 7.8。\n速算口诀：除数三/四位数，先算首商，再看余数占除数的比例。", "explain": "617×7＝4319；617×8＝4936 已经超过 4823。所以商在 7～8 之间，且 4823－4319＝504，504÷617≈0.82，故约 7.8，选 C。", "tip": "别用笔硬除到小数点后两位：资料分析只要选到“最接近”的选项，首商＋余数比例就够了。", "hard": "余数与除数的比例是判断小数的关键，别忘了这一步，否则容易在 7.8 和 6.8 之间犹豫。"}, {"type": "pure", "level": "基础", "stem": "计算 2023.4 ÷ 3.87，结果最接近下列哪一项？", "options": ["403", "523", "691", "829"], "answer": ["B"], "method": "把除数看成 3.9：2023.4÷3.9≈518.8；也可以直接验证 3.87×523＝2024.0，与 2023.4 几乎相等。", "explain": "3.87≈3.9，2023.4÷3.9≈519；再用 3.87×523＝2024.0 验证，误差仅 0.6，所以答案是 523（B）。", "tip": "除数四舍五入后要反向验证一次（乘回去），避免估算误差把答案推到相邻选项。", "hard": "3.87 与 3.9 的差异约为 0.8%，在大数值上会放大到 15 左右，正好决定 B 还是 C。"}, {"type": "pure", "level": "基础", "stem": "某指标由 428 增长到 561，增长率最接近下列哪一项？", "options": ["26%", "31%", "36%", "41%"], "answer": ["B"], "method": "增长率＝(现期－基期)÷基期＝(561－428)÷428＝133÷428。\n速算：428×30%＝128.4，略小于 133，所以略高于 30% → 约 31%。", "explain": "133÷428：先算 1/4＝25%（107），再补 26（约 6%），合计约 31%，选 B。", "tip": "增长率的分母一定是基期（428），不是现期。分母搞反是最高频的低级错误。", "hard": "选项间隔只有 5 个百分点，必须用“先取整百分数、再补差”的方式逼近，不能只看大概。"}, {"type": "pure", "level": "基础", "stem": "部分值 1586，整体值 4820，部分占整体的比重最接近下列哪一项？", "options": ["33%", "28%", "43%", "38%"], "answer": ["A"], "method": "整体×1/3＝4820÷3≈1606.7，比 1586 略大 → 比重应略小于 1/3（33.3%）→ 约 33%。", "explain": "4820×0.33＝1590.6，与 1586 只差 4.6，说明比重几乎正好是 33%，选 A。", "tip": "比重的常用基准：1/3≈33.3%、1/4＝25%、2/5＝40%、3/4＝75%。先找最近基准再微调，比硬除快得多。", "hard": "选项 28% 与 33% 的差距看似明显，但如果用“1586/4820≈0.29”的粗估（把 4820 当 5500）就会选错。"}, {"type": "pure", "level": "基础", "stem": "计算 25.6% ＋ 18.9% － 9.4%，结果最接近下列哪一项？", "options": ["16.4%", "25.1%", "45.1%", "35.1%"], "answer": ["D"], "method": "整数部分先加：25＋18－9＝34；小数部分：0.6＋0.9－0.4＝1.1；合计 35.1%。", "explain": "25.6%＋18.9%＝44.5%，44.5%－9.4%＝35.1%，选 D。", "tip": "百分数的加减可以直接当小数运算，但要小心借位：44.5－9.4 容易错算成 34.1 或 35.9。", "hard": "多步加减要先合并同号的项（这里先加后减），减少一次心算，出错率明显下降。"}, {"type": "pure", "level": "基础", "stem": "计算 3842 ÷ 612，结果最接近下列哪一项？", "options": ["4.3", "5.3", "6.3", "7.3"], "answer": ["C"], "method": "612×6＝3672，3842－3672＝170；170÷612≈0.28 → 商约 6.3。", "explain": "612×6＝3672，612×7＝4284 已超过 3842，所以商在 6～7 之间，约为 6.3，选 C。", "tip": "除数接近 600 时，可用“6 倍”作锚点；余数不到除数的三分之一，商的小数部分就小于 0.35。", "hard": "若把 612 粗看成 600 直接算 3842/600＝6.4，会倾向选 C 也正确，但如果选项里有 6.4 就容易被带偏——估算后要用乘法回验。"}, {"type": "pure", "level": "进阶", "stem": "某数据连续两年分别增长 12% 和 9%，两年累计增长率最接近下列哪一项？", "options": ["22.1%", "20.1%", "23.1%", "26.1%"], "answer": ["A"], "method": "两年累计＝(1＋12%)×(1＋9%)－1＝12%＋9%＋12%×9%＝21%＋1.08%≈22.1%。", "explain": "12%＋9%＝21%，再加上两者的乘积 1.08%，合计约 22.1%，选 A。", "tip": "不能简单相加：相加是 21%，漏掉了交叉项 1.08%，差别正好落在选项之间。", "hard": "这是最常见的“间隔增长率”陷阱，乘积项看似很小，但选项设计得只差一个百分点左右。"}, {"type": "pure", "level": "进阶", "stem": "下列四个分数中，数值最大的是？", "options": ["3/7", "4/9", "5/11", "6/13"], "answer": ["D"], "method": "四个分数都是“分子＋2、分母＋2”的形式（n/(2n－1)）：分子分母同时加同一个正数时，分数趋近 1/2，且原值越小、增幅越大？\n正确思路：写成 1/2 的形式看差距 —— 3/7＝1/2－1/14，4/9＝1/2－1/18，5/11＝1/2－1/22，6/13＝1/2－1/26，差越小值越大 → 6/13 最大。", "explain": "3/7≈0.429，4/9≈0.444，5/11≈0.455，6/13≈0.462，最大的是 6/13，选 D。", "tip": "不要一上来就通分。凡是分子分母差相同的分数，用“与 1/2 的差距”比较最快。", "hard": "这类题的规律是：分子越大越接近 1/2，容易误以为“小分数更小但更保险”而选反。"}, {"type": "pure", "level": "基础", "stem": "57.1% 最接近下列哪个分数？", "options": ["3/5", "4/7", "5/9", "7/12"], "answer": ["B"], "method": "记住常用换算：1/7≈14.3%、2/7≈28.6%、3/7≈42.9%、4/7≈57.1%。", "explain": "4/7＝0.5714→57.1%，故选 B。其余：3/5＝60%，5/9≈55.6%，7/12≈58.3%。", "tip": "资料分析里 1/7 到 6/7 的百分数是必背表，考到比重、增速换算时能省大量时间。", "hard": "7/12≈58.3% 与 57.1% 只差 1.2 个百分点，不背表很容易误选。"}, {"type": "pure", "level": "基础", "stem": "计算 1374 × 1.38，结果最接近下列哪一项？", "options": ["1450", "1690", "1890", "2100"], "answer": ["C"], "method": "1374×1.38＝1374＋1374×0.38；1374×0.38＝1374×(0.4－0.02)＝549.6－27.5≈522 → 合计 1896。", "explain": "1374×1.38≈1896，最接近 1890，选 C。", "tip": "乘 1.x 时拆成“原数＋增量”比整体乘更快；0.38 拆成 0.4－0.02 可避免进位错。", "hard": "增量部分 522 和选项差距有关：若把 0.38 当 0.4 算，会得到 1924，接近 1890 与 2100 中间，容易犹豫。"}, {"type": "pure", "level": "基础", "stem": "五个数据 38、42、51、47、62 的平均数是多少？", "options": ["44", "46", "47", "48"], "answer": ["D"], "method": "取基准 50：偏差为 －12、－8、＋1、－3、＋12，合计 －10；平均值＝50＋(－10÷5)＝50－2＝48。", "explain": "总和 38＋42＋51＋47＋62＝240，240÷5＝48，选 D。", "tip": "平均数题用“基准＋偏差”法最快，尤其数据都围绕某个整数时；直接竖加容易出错。", "hard": "差值总和是 －10，别忘记要除以个数 5，再回到基准上，最后一步方向容易搞反。"}, {"type": "pure", "level": "基础", "stem": "计算 9832 － 4177，结果最接近下列哪一项？", "options": ["5655", "5505", "5805", "6005"], "answer": ["A"], "method": "先整算：9800－4200＝5600，再补零头：＋32＋23＝55 → 5655。", "explain": "9832－4177＝5655，选 A。", "tip": "减法用“凑整后再加回零头”，比逐位借位稳，也不容易在借位上丢 1。", "hard": "零头是“＋32＋23”而不是“－32＋23”，方向看错就会得到 5591 之类的结果。"}, {"type": "applied", "level": "基础", "stem": "问：该市 2023 年地区生产总值同比增长约多少？", "data": "【材料】某市地区生产总值：\n2022 年 12480 亿元；2023 年 13602 亿元。", "options": ["7.0%", "8.0%", "9.0%", "10.0%"], "answer": ["C"], "method": "增长率＝(现期－基期)÷基期＝(13602－12480)÷12480＝1122÷12480。\n速算：12480×9%＝1123.2，与 1122 几乎相等 → 正好约 9%。", "explain": "增量 1122 亿元，1122÷12480≈8.99%，故选 9.0%（C）。", "tip": "基期一定是 12480（去年），不是 13602。反向用“现期×增速”验证：12480×9%＝1123≈1122。", "hard": "选项间距只有 1 个百分点，必须做一次乘法验证，光靠“约 9%”的直觉很容易选成 8%。"}, {"type": "applied", "level": "基础", "stem": "问：2023 年该县税收收入占财政收入的比重约为多少？", "data": "【材料】2023 年某县财政收入 86.4 亿元，其中税收收入 65.7 亿元。", "options": ["71%", "76%", "81%", "86%"], "answer": ["B"], "method": "先找基准：86.4×3/4＝64.8，略小于 65.7 → 比重比 75% 稍高，约 76%。", "explain": "65.7÷86.4≈0.7604→76%，选 B。", "tip": "用 3/4 作锚点最省事；若用 4/5＝80% 去比，会误判成 81%。", "hard": "余数法验证：86.4×76%＝65.7，正好对上，说明答案误差在 0.1 个百分点内。"}, {"type": "applied", "level": "进阶", "stem": "问：2019—2023 年，该市快递业务量年均增长量约为多少？", "data": "【材料】2019 年某市快递业务量 12.5 亿件；2023 年 24.6 亿件。", "options": ["3.0 亿件", "2.4 亿件", "3.6 亿件", "4.2 亿件"], "answer": ["A"], "method": "年均增长量＝(末期值－初期值)÷间隔年数＝(24.6－12.5)÷(2023－2019)＝12.1÷4≈3.03。", "explain": "总增量 12.1 亿件，间隔 4 年，12.1÷4≈3.0 亿件，选 A。", "tip": "间隔年数是 4 不是 5（2023－2019）！这是“年均增长量”最高频的坑。", "hard": "如果误用“年数＝5”会得到 2.4 亿件，正好是干扰项 B，出题人就是冲这个来的。"}, {"type": "applied", "level": "进阶", "stem": "问：2021—2023 年该园区产值的年均增长率约为多少？", "data": "【材料】某园区产值：2021 年 25 亿元；2023 年 36 亿元。", "options": ["12%", "15%", "20%", "25%"], "answer": ["C"], "method": "两年年均增长率 r 满足 (1＋r)²＝末期÷初期＝36÷25＝1.44。\n常用平方数：1.2²＝1.44 → r＝20%。", "explain": "36÷25＝1.44，开平方得 1.2，即年均增长 20%，选 C。", "tip": "两年年均增长率用开平方（1.44 的开方是 1.2，一定要背 1.1²=1.21、1.2²=1.44、1.3²=1.69）。", "hard": "别把“总增长率 44%”直接除以 2 得 22%（无此选项），也不能选 25%（那是把 44% 当单年）。"}, {"type": "applied", "level": "进阶", "stem": "问：2023 年该市第三产业增加值占 GDP 的比重与上年相比约：", "data": "【材料】2023 年某市第三产业增加值 8320 亿元，同比增长 6.2%；全市地区生产总值 15600 亿元，同比增长 4.8%。", "options": ["下降 0.7 个百分点", "上升 0.7 个百分点", "上升 2.1 个百分点", "下降 2.1 个百分点"], "answer": ["B"], "method": "① 现期比重：8320÷15600≈53.3%。\n② 基期比重：(8320÷1.062)÷(15600÷1.048)＝7834÷14885≈52.6%。\n③ 两者相减：53.3%－52.6%＝＋0.7 个百分点。\n口诀：部分增速(6.2%)＞整体增速(4.8%) → 比重上升。", "explain": "部分增速高于整体增速，比重必然上升；用两期比重差公式验证：比重差≈现期比重×(部分增速－整体增速)÷(1＋部分增速)≈53.3%×1.4%÷1.062≈0.70 个百分点，选 B。", "tip": "先判方向（部分增速＞整体增速 → 上升），只在“上升”的选项里挑，能直接排除一半选项。", "hard": "两期比重差的公式里分母是 (1＋部分增速)，不是 (1＋整体增速)；用错方向或数量级会得到 2.1 那个干扰值。"}, {"type": "applied", "level": "进阶", "stem": "问：2023 年该市研发投入总额约为多少？", "data": "【材料】2023 年某市高新技术企业研发投入 246 亿元，占全市研发投入总额的 61.5%。", "options": ["340 亿元", "360 亿元", "380 亿元", "400 亿元"], "answer": ["D"], "method": "整体＝部分÷比重＝246÷61.5%。\n速算：61.5%≈5/8 → 246×8÷5＝393.6≈400 亿元。", "explain": "246÷0.615＝400（亿元），选 D。", "tip": "“已知部分求整体”要用除法；把 61.5% 看成 5/8 后计算量骤减。", "hard": "常见错法：246×61.5%≈151（乘错了）。看到“占……的 X%”先想清楚是求整体还是求部分。"}, {"type": "applied", "level": "基础", "stem": "问：2023 年 A 省粮食产量约是 B 省的多少倍？", "data": "【材料】2023 年 A 省粮食产量 4250 万吨，B 省 1062.5 万吨。", "options": ["2 倍", "3 倍", "4 倍", "5 倍"], "answer": ["C"], "method": "验证法：1062.5×4＝4250，正好相等 → 4 倍。", "explain": "4250÷1062.5＝4，选 C。", "tip": "倍数题用“乘回去”验证最快：拿干扰选项各乘一次，谁正好等于分子就是答案。", "hard": "选项都是整数倍，说明出题人想让你用“凑数法”而不是硬除，别浪费时间去算小数部分。"}, {"type": "applied", "level": "进阶", "stem": "问：2022 年全国实物商品网上零售额约为多少？", "data": "【材料】2023 年全国实物商品网上零售额 13.0 万亿元，同比增长 8.4%。", "options": ["11.0 万亿元", "12.0 万亿元", "13.0 万亿元", "14.0 万亿元"], "answer": ["B"], "method": "求基期：基期＝现期÷(1＋增长率)＝13.0÷1.084≈12.0。\n速算：1.084≈1.1 → 13.0÷1.1≈11.8，说明答案在 12 附近（用 1.084 精算刚好 12.0）。", "explain": "13.0÷1.084＝11.99≈12.0 万亿元，选 B。", "tip": "求基期是除法，求增长量是乘法——13.0×8.4% 得到的是增量，不是基期。", "hard": "简算时把 1.084 当 1.1 会低估基期（得 11.8），正好滑向干扰项 11.0 一侧，需要用“略小于 1.1”修正回 12.0。"}]}, {"set": 2, "date": "2026-09-29", "session": "day", "title": "资料分析速算训练 · 第 2 批（直除估算 / 增长率 / 间隔增长 / 年均增长 / 两期比重）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "3417 ÷ 47.3 的结果最接近（　）", "data": "", "options": ["68.5", "72.2", "76.4", "80.1"], "answer": ["B"], "method": "首数法（直除）：\n① 先看首数：47.3×7=331.1，3417 里能放 7 个 47.3；\n② 再补一位：47.3×72=3405.6，余 11.4；\n③ 个位再补：11.4÷47.3≈0.24，合计约 72.2。", "explain": "47.3×72=3405.6，3417-3405.6=11.4，11.4÷47.3≈0.24，所以 3417÷47.3≈72.2，选 B。", "tip": "不要一上来就精确长除。先定“首位商 7”，把选项按首位筛掉 68.5 以下；再用尾数定 72.2。", "hard": "选项 68.5 与 72.2 相差不到 5%，若只估到“70 左右”就会左右摇摆，必须算到小数点后一位。"}, {"type": "pure", "level": "基础", "stem": "1234.5 × 12.5% 约等于（　）", "data": "", "options": ["148.1", "154.3", "162.5", "171.2"], "answer": ["B"], "method": "化分数（最省力的一招）：\n① 12.5% = 1/8；\n② 1234.5 ÷ 8 = 154.3。", "explain": "12.5% 化为 1/8，1234.5÷8=154.3125≈154.3，选 B。", "tip": "记住常用化分数：12.5%=1/8、25%=1/4、37.5%=3/8、62.5%=5/8、16.7%≈1/6、14.3%≈1/7。", "hard": "选项 148.1 是把 12% 当成 12.5% 算出的结果（1234.5×0.12=148.1），速度一快就容易掉进去。"}, {"type": "pure", "level": "基础", "stem": "把 6/7 化为百分数（保留一位小数），约为（　）", "data": "", "options": ["78.6%", "82.4%", "85.7%", "88.9%"], "answer": ["C"], "method": "化分数直记：\n① 1/7≈14.3%，6/7＝1-1/7；\n② 1-14.3%＝85.7%。", "explain": "1/7≈14.3%，故 6/7≈85.7%，选 C。也可直除 6÷7=0.857。", "tip": "先记 1/7≈14.3%，再推 2/7≈28.6%、3/7≈42.9%、5/7≈71.4%，比现算快得多。", "hard": "选项 82.4% 是 1/7×… 记反（把 5/7=71.4% 记成 14.3% 再乘错）时出现的结果，务必用 1-1/7 反推核对。"}, {"type": "pure", "level": "基础", "stem": "今年某指标为 1680，去年为 1400，则同比增长（　）", "data": "", "options": ["16.7%", "20.0%", "22.4%", "25.0%"], "answer": ["B"], "method": "增长率＝（今-去）÷去：\n① 增量 1680-1400=280；\n② 280÷1400=0.2=20%。", "explain": "(1680-1400)÷1400=280÷1400=20.0%，选 B。", "tip": "分母必须是“去年的量”（基期）。用今年的量做分母就掉进干扰项。", "hard": "干扰项 16.7% 就是把分母换成今年算的：280÷1680=16.7%。"}, {"type": "pure", "level": "进阶", "stem": "今年某指标为 2460，同比增长 15%，则同比增长量约为（　）", "data": "", "options": ["276", "321", "369", "398"], "answer": ["B"], "method": "已知“现期+增长率”求增长量：\n① 先求基期：2460÷1.15≈2139；\n② 增长量＝2460-2139≈321。\n（速算式：增长量＝现期×r/(1+r)＝2460×0.15/1.15）", "explain": "基期＝2460÷1.15≈2139.1，增长量＝2460-2139.1≈320.9≈321，选 B。", "tip": "绝不能直接 2460×15%=369！那个数是以“基期”为底的，本题给的是现期。", "hard": "干扰项 369 就是“现期×增长率”的错算，也是最常见的失分点。"}, {"type": "pure", "level": "进阶", "stem": "2026 年比 2024 年增长多少？已知 2025 年同比增长 20%，2026 年同比增长 25%。", "data": "", "options": ["45.0%", "47.5%", "50.0%", "55.0%"], "answer": ["C"], "method": "间隔增长率：\n① 公式 r＝r1+r2+r1×r2；\n② 20%+25%+20%×25%=45%+5%＝50%。", "explain": "1.2×1.25=1.50，即增长 50%，选 C。", "tip": "千万别把两个增长率直接相加得 45%（漏掉乘积项 5%）。", "hard": "干扰项 45% 就是漏乘 r1×r2 的结果；间隔越久、数值越大，漏乘误差越明显。"}, {"type": "pure", "level": "基础", "stem": "2019 年某产量为 1200，2024 年为 2400，则这期间年均增长量约为（　）", "data": "", "options": ["200", "240", "300", "400"], "answer": ["B"], "method": "年均增长量＝（末期-初期）÷（年份差）：\n① 年份差＝2024-2019=5；\n② (2400-1200)÷5=240。", "explain": "(2400-1200)÷5=240，选 B。", "tip": "年份差是 5 不是 6（2019→2024 跨 5 年）。这个“差一年”的坑每年都有人踩。", "hard": "干扰项 200 是用 6 年算的（1200÷6=200），务必数清“间隔年数”。"}, {"type": "pure", "level": "进阶", "stem": "某量从 1000 增长到 1600，历时 4 年，则年均增长率约为（　）", "data": "", "options": ["9.8%", "12.5%", "15.0%", "18.6%"], "answer": ["B"], "method": "年均增长率（开平方思路）：\n① 倍数关系：(1+r)^4=1.6；\n② 两边开两次平方：1.6^0.5≈1.265，再开平方≈1.125；\n③ r≈12.5%。", "explain": "1.6^(1/4)≈1.125，故年均增长率≈12.5%，选 B。", "tip": "绝不能把总增长率 60% 除以 4 得 15%！年均增长率是“几何平均”，一定小于算术平均。", "hard": "干扰项 15.0% 就是 60%÷4 的错算；真正的结果必然更小，可据此排除。"}, {"type": "pure", "level": "进阶", "stem": "总体今年为 5000（同比+10%），其中某部分今年为 1200（同比+20%），则该部分占比比去年（　）", "data": "", "options": ["提高约 1.0 个百分点", "提高约 2.0 个百分点", "下降约 2.0 个百分点", "基本持平"], "answer": ["B"], "method": "两期比重差：\n① 今年占比＝1200÷5000=24%；\n② 去年占比＝(1200÷1.2)÷(5000÷1.1)=1000÷4545.5≈22%；\n③ 差＝24%-22%＝+2 个百分点。", "explain": "部分增速(20%)>总体增速(10%)，占比必然上升；具体由 22% 升至 24%，提高约 2.0 个百分点，选 B。", "tip": "先判方向再算数值：部分增速快于总体，占比就上升，可先排除“下降”。", "hard": "干扰项 1.0 是只算“增量比”的粗估；要注意两期比重差＝今占比-去占比，不能只用增速差相减。"}, {"type": "pure", "level": "基础", "stem": "12345 是 2058 的多少倍（保留一位小数）？", "data": "", "options": ["5.0 倍", "5.6 倍", "6.0 倍", "6.5 倍"], "answer": ["C"], "method": "倍数＝A÷B：\n① 2058×6=12348；\n② 12345 略小于 12348，故≈6.0。", "explain": "12345÷2058≈5.999≈6.0 倍，选 C。", "tip": "倍数问题先试整数倍：×6 正好贴近，一步定位。", "hard": "选项 5.6 是“差值÷分母”之类错算的口径；记住倍数＝除法，不是减法比较。"}, {"type": "pure", "level": "基础", "stem": "已知 5 个数的平均数为 42.6，其中 4 个是 38、45、41、44，则第 5 个数是（　）", "data": "", "options": ["43", "44", "45", "46"], "answer": ["C"], "method": "用总量倒推：\n① 总数＝42.6×5=213；\n② 前四个之和＝38+45+41+44=168；\n③ 第 5 个＝213-168=45。", "explain": "42.6×5=213，213-168=45，选 C。", "tip": "平均数的题一律“先求总量、再做减法”，比逐个凑数稳。", "hard": "本题干扰项 43/44/46 都紧贴答案，必须精确算总量，不能靠目测平均。"}, {"type": "pure", "level": "进阶", "stem": "某数先上涨 20%，再下跌 10%，则最终比原数（　）", "data": "", "options": ["上涨 8%", "上涨 10%", "上涨 12%", "上涨 30%"], "answer": ["A"], "method": "连续变化用乘法：\n① 1×1.2×0.9=1.08；\n② 比原数上涨 8%。", "explain": "1.2×0.9=1.08，即上涨 8%，选 A。", "tip": "涨跌不能直接相减（20%-10%≠10%）：先涨后跌的“底数”变了。", "hard": "干扰项 10% 就是 20%-10% 的错算；只有“先跌后涨”同比例才会回到原点，本题不是。"}, {"type": "applied", "level": "进阶", "stem": "2024 年小麦产量占粮食总产量的比重约为（　）", "data": "【材料】2025 年某省粮食总产量 3200 万吨，比上年增长 4.0%；其中小麦产量 1200 万吨，比上年增长 2.0%。", "options": ["34.5%", "36.1%", "38.2%", "40.6%"], "answer": ["C"], "method": "求“基期比重”，用两期数据各自还原：\n① 2024 年总产量＝3200÷1.04≈3076.9；\n② 2024 年小麦＝1200÷1.02≈1176.5；\n③ 比重＝1176.5÷3076.9≈38.2%。", "explain": "3076.9 与 1176.5 相除得 38.2%，选 C。", "tip": "求“去年的比重”必须把分子分母都还原到去年，不能拿今年的 1200÷3200=37.5% 交差。", "hard": "干扰项 37.5% 正是“今年比重”的错用；注意题干问的是 2024 年。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市社会消费品零售总额比上年增长约多少亿元（　）", "data": "【材料】2025 年某市社会消费品零售总额 4800 亿元，同比增长 6.5%。", "options": ["265 亿元", "293 亿元", "312 亿元", "330 亿元"], "answer": ["B"], "method": "已知现期+增长率求增长量：\n① 基期＝4800÷1.065≈4507；\n② 增长量＝4800-4507≈293。\n也可用 4800×6.5%/1.065≈293。", "explain": "4800÷1.065≈4507.0，4800-4507.0=293，选 B。", "tip": "不能直接 4800×6.5%=312（那是拿现期当基期）。", "hard": "干扰项 312 是典型的“现期×增长率”错算，本题问增长量必须除 (1+r)。"}, {"type": "applied", "level": "进阶", "stem": "2026 年营收比 2024 年增长约（　）", "data": "【材料】某企业 2024 年营收为 50 亿元，2025 年同比增长 12%，2026 年同比增长 15%。", "options": ["25.0%", "27.0%", "28.8%", "30.5%"], "answer": ["C"], "method": "间隔（复合）增长率：\n① r＝12%+15%+12%×15%；\n② ＝27%+1.8%＝28.8%。", "explain": "1.12×1.15=1.288，即增长 28.8%，选 C。", "tip": "两个增长率相加得 27% 是漏掉了乘积项 1.8%。", "hard": "干扰项 27.0% 就是漏乘 r1×r2；间隔增长率必须加乘积项。"}, {"type": "applied", "level": "基础", "stem": "2019—2024 年该省新能源汽车产量的年均增长量约为（　）", "data": "【材料】2019 年某省新能源汽车产量为 25.0 万辆，2024 年增至 62.5 万辆。", "options": ["6.3 万辆", "7.5 万辆", "9.4 万辆", "12.5 万辆"], "answer": ["B"], "method": "年均增长量＝（末期-初期）÷年份差：\n① 年份差＝5；\n② (62.5-25.0)÷5=7.5。", "explain": "(62.5-25.0)÷5=37.5÷5=7.5 万辆，选 B。", "tip": "年份差是 5 不是 6；除以 6 会得到 6.25（贴近干扰项 6.3）。", "hard": "干扰项 6.3 就是“除以 6 年”的错算；数年份差时别把 2019 本身也算一年。"}, {"type": "applied", "level": "进阶", "stem": "2025 年出口交货值占主营业务收入的比重，比上年约（　）", "data": "【材料】2025 年某行业主营业务收入 8000 亿元，同比增长 8%；其中出口交货值 2000 亿元，同比增长 16%。", "options": ["提高 0.8 个百分点", "提高 1.7 个百分点", "提高 2.6 个百分点", "下降 1.7 个百分点"], "answer": ["B"], "method": "两期比重差：\n① 今年占比＝2000÷8000=25.0%；\n② 去年占比＝(2000÷1.16)÷(8000÷1.08)≈1724.1÷7407.4≈23.3%；\n③ 差＝25.0%-23.3%＝+1.7 个百分点。", "explain": "部分增速(16%)>总体增速(8%)，比重上升；由 23.3% 升到 25.0%，提高约 1.7 个百分点，选 B。", "tip": "先看增速大小即可定方向：部分增速快则比重升，可直接排除“下降”。", "hard": "干扰项 0.8 是“增速差 8%×占比”类型的粗估；两期比重差要按占比相减算，不能只比增速。"}, {"type": "applied", "level": "进阶", "stem": "2024 年 1—8 月该市基础设施投资占固定资产投资的比重约为（　）", "data": "【材料】某市 2025 年 1—8 月完成固定资产投资 3456 亿元，同比增长 5%；其中基础设施投资 1382 亿元，同比增长 3%。", "options": ["33.4%", "36.2%", "40.8%", "45.1%"], "answer": ["C"], "method": "基期比重（分子分母各自还原）：\n① 2024 年总投资＝3456÷1.05≈3291.4；\n② 2024 年基础设施＝1382÷1.03≈1341.7；\n③ 比重＝1341.7÷3291.4≈40.8%。", "explain": "1341.7÷3291.4≈40.8%，选 C。", "tip": "别用今年的 1382÷3456=40.0% 直接答；问的是 2024 年，须还原基期。", "hard": "今年比重 40.0% 与正确答案 40.8% 很接近，只有还原基期才能分辨。"}, {"type": "applied", "level": "进阶", "stem": "某地区快递业务量从 2020 年到 2025 年的年均增长率约为（　）", "data": "【材料】2025 年某地区快递业务量 120 亿件，2020 年为 60 亿件。", "options": ["10.0%", "12.5%", "14.9%", "20.0%"], "answer": ["C"], "method": "年均增长率（倍数法）：\n① 倍数＝120÷60=2，即 (1+r)^5=2；\n② 2 开 5 次方≈1.149；\n③ r≈14.9%。", "explain": "2^(1/5)≈1.149，年均增长率≈14.9%，选 C。", "tip": "不能把总增长率 100% 除以 5 得 20%——几何平均必小于算术平均。", "hard": "干扰项 20.0% 就是 100%÷5 的错算；“5 年翻一番”，记住对应年均约 15%（72 法则：72÷5≈14.4）。"}, {"type": "applied", "level": "进阶", "stem": "2025 年该省居民消费支出占人均可支配收入的比重，与上年相比约（　）", "data": "【材料】2025 年某省居民人均可支配收入 42000 元，同比增长 5.5%；居民人均消费支出 28000 元，同比增长 6.0%。", "options": ["下降 0.3 个百分点", "提高 0.3 个百分点", "提高 1.2 个百分点", "提高 2.4 个百分点"], "answer": ["B"], "method": "两期比重差：\n① 今年占比＝28000÷42000≈66.67%；\n② 去年占比＝(28000÷1.06)÷(42000÷1.055)=26415.1÷39810.4≈66.35%；\n③ 差＝66.67%-66.35%≈+0.3 个百分点。", "explain": "消费支出增速(6.0%)略快于收入增速(5.5%)，占比小幅上升约 0.3 个百分点，选 B。", "tip": "增速接近时，两期比重差往往很小（零点几个百分点），要精算，不能凭感觉估成 1~2 个百分点。", "hard": "干扰项 1.2/2.4 是把分子分母做错位相减的产物；增速只差 0.5 个百分点，比重要变化应远小于 1 个百分点。"}]}, {"set": 3, "date": "2026-09-30", "session": "day", "title": "资料分析速算训练 · 第 3 批（首数直除 / 增长率与增长量 / 间隔增长 / 年均增长 / 比重与两期比重差 / 倍数与平均数）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "5638 ÷ 62.5 的结果最接近（　）", "data": "", "options": ["90.2", "84.6", "96.4", "78.9"], "answer": ["A"], "method": "首数直除：\n① 定首位：62.5×9＝562.5，5638 里能放 90 个 62.5；\n② 精确一位：62.5×90＝5625，余 13；\n③ 补小数：13÷62.5≈0.21，合计约 90.2。", "explain": "62.5×90＝5625，5638−5625＝13，13÷62.5≈0.21，所以 5638÷62.5≈90.2，选 A。", "tip": "先定“商的首位是 9”，把 84.6、78.9 这类首位为 8 的选项直接排除，再用余数定到小数点后一位。", "hard": "90.2 与 96.4 相差约 7%，只估到“九十多”会摇摆，必须算到小数点后一位。"}, {"type": "pure", "level": "基础", "stem": "247 × 38.2% 的结果最接近（　）", "data": "", "options": ["84.4", "94.4", "103.7", "114.8"], "answer": ["B"], "method": "百分数化小数再乘：\n① 38.2%≈0.382；\n② 247×0.382＝247×0.38＋247×0.002＝93.86＋0.49≈94.4。", "explain": "247×38.2%＝247×0.382≈94.35，最接近 94.4，选 B。", "tip": "把 38.2% 拆成 38%＋0.2% 更好算；直接用 40% 会得到 98.8，容易误选 103.7 附近的项。", "hard": "选项间隔约 10，若把 38.2% 当成 42% 就会滑到 103.7，注意别四舍五入过头。"}, {"type": "pure", "level": "基础", "stem": "某指标由 3200 增长到 4160，增长率约为（　）", "data": "", "options": ["22%", "26%", "30%", "34%"], "answer": ["C"], "method": "增长率＝（现期−基期）÷基期：\n① 增长量＝4160−3200＝960；\n② 960÷3200＝0.3＝30%。", "explain": "（4160−3200）÷3200＝960÷3200＝30%，选 C。", "tip": "分母必须是基期（3200），不能用现期（4160）当分母，否则会得到约 23% 的错值。", "hard": "干扰项 22% 正是“960÷4160≈23%”的错算结果，方向一错就掉进去。"}, {"type": "pure", "level": "基础", "stem": "某量连续两年分别增长 20% 和 25%，两年合计增长约为（　）", "data": "", "options": ["40%", "45%", "48%", "50%"], "answer": ["D"], "method": "间隔（复合）增长率：\n① 用（1＋r1）（1＋r2）−1；\n② 1.2×1.25＝1.5；\n③ 1.5−1＝0.5＝50%。", "explain": "1.2×1.25＝1.5，两年合计增长 50%，选 D。", "tip": "不能直接相加（20%＋25%＝45%），复合增长要相乘，第二年的增长是在“已经涨过”的基数上发生的。", "hard": "干扰项 45% 就是“直接相加”的经典错法，凡是问“两年合计/间隔增长”，一律用乘法。"}, {"type": "pure", "level": "基础", "stem": "某市 GDP 由 2019 年的 480 亿元增至 2024 年的 780 亿元，年均增长量约为（　）", "data": "", "options": ["60 亿元", "50 亿元", "75 亿元", "300 亿元"], "answer": ["A"], "method": "年均增长量＝（末期−初期）÷年数差：\n① 增长总量＝780−480＝300；\n② 年数＝2024−2019＝5；\n③ 300÷5＝60。", "explain": "（780−480）÷（2024−2019）＝300÷5＝60 亿元，选 A。", "tip": "年数是“年份差”（5 年），不是“年份个数”（6 个）。用 6 会得到 50，正好是干扰项。", "hard": "选项里同时放了 50（年数算成 6）和 300（把总量当年均量），两个坑都要防。"}, {"type": "pure", "level": "进阶", "stem": "某指标 4 年间从 100 增至 146.41，年均增长率约为（　）", "data": "", "options": ["8%", "10%", "12%", "14%"], "answer": ["B"], "method": "年均增长率＝（末期÷初期）^(1÷年数)−1：\n① 146.41÷100＝1.4641；\n② 1.4641 开 4 次方：1.1^4＝1.4641；\n③ 1.1−1＝10%。", "explain": "因为 1.1^4＝1.4641，所以年均增长率＝10%，选 B。", "tip": "开平方开不出整数时，用代入法：把选项的 1+r 试乘 4 次，看哪个接近 1.4641。", "hard": "年均增长率不能用“总增长÷年数”。总增长 46.41%÷4＝11.6%，会误选 12%。"}, {"type": "pure", "level": "基础", "stem": "某年 A 项为 840，总体为 3500，A 占总体比重约为（　）", "data": "", "options": ["18%", "21%", "24%", "27%"], "answer": ["C"], "method": "比重＝部分÷总体：\n① 840÷3500；\n② 3500×24%＝840；\n③ 故比重为 24%。", "explain": "840÷3500＝0.24＝24%，选 C。", "tip": "用“乘回去验算”最快：3500×24%＝840，正好对上，直接选定。", "hard": "若把分母看成 3200 或分子看成 940，都会偏到 21% 或 27%，注意抄数。"}, {"type": "pure", "level": "进阶", "stem": "某部分占总体的比重为 40%，若总体增长 10%、该部分增长 20%，则新的比重约为（　）", "data": "", "options": ["40.0%", "42.0%", "43.0%", "43.6%"], "answer": ["D"], "method": "两期比重：新比重＝旧比重×（1＋部分增速）÷（1＋总体增速）：\n① 0.40×1.2＝0.48；\n② 0.48÷1.1≈0.4364；\n③ 即约 43.6%。", "explain": "0.40×1.2÷1.1＝0.48÷1.1≈43.6%，选 D。", "tip": "部分增速快于总体，比重必上升；但升幅不是 20%−10%＝10 个百分点，要用乘法算。", "hard": "干扰项 42.0% 是“0.40×（1＋0.2−0.1）”的错算；两期比重必须用除法，不能加减。"}, {"type": "pure", "level": "进阶", "stem": "甲是乙的 3.6 倍。若甲增长 10%、乙增长 20%，则现在甲是乙的多少倍（　）", "data": "", "options": ["3.3", "3.0", "3.6", "3.9"], "answer": ["A"], "method": "倍数变化＝原倍数×（1＋甲增速）÷（1＋乙增速）：\n① 3.6×1.1＝3.96；\n② 3.96÷1.2＝3.3。", "explain": "3.6×1.1÷1.2＝3.3，选 A。", "tip": "分母增速快于分子时倍数下降；3.6 不会保持不变（除非两者增速相同）。", "hard": "干扰项 3.9 是“3.6×1.1”后忘了除 1.2 的结果，别漏掉分母的增长。"}, {"type": "pure", "level": "基础", "stem": "某地区粮食总产 1245 万吨，播种面积 830 万公顷，平均单产约为多少吨/公顷（　）", "data": "", "options": ["1.2", "1.5", "1.8", "2.1"], "answer": ["B"], "method": "平均数＝总量÷份数：\n① 1245÷830；\n② 830×1.5＝1245；\n③ 故为 1.5 吨/公顷。", "explain": "1245÷830＝1.5，选 B。", "tip": "平均数题先看单位对不对（吨/公顷），再用“份数×选项”反验。", "hard": "若把 1245 看成 1245÷0.83 之类，会偏到 1.8 以上，注意单位都是“万”，可约掉。"}, {"type": "pure", "level": "基础", "stem": "480 的 12.5% 是（　）", "data": "", "options": ["48", "54", "60", "72"], "answer": ["C"], "method": "化分数：\n① 12.5%＝1/8；\n② 480÷8＝60。", "explain": "480×12.5%＝480÷8＝60，选 C。", "tip": "常用化分数背熟：1/8＝12.5%、1/6≈16.7%、1/7≈14.3%、1/9≈11.1%。", "hard": "干扰项 48 是“480×10%”的错算，把 12.5% 当 10% 就会错。"}, {"type": "pure", "level": "进阶", "stem": "（1＋15%）×（1−10%）−1 的结果是（　）", "data": "", "options": ["2.5%", "3.0%", "3.2%", "3.5%"], "answer": ["D"], "method": "先涨后跌的复合变化：\n① 1.15×0.90＝1.035；\n② 1.035−1＝0.035＝3.5%。", "explain": "1.15×0.9＝1.035，净变化 3.5%，选 D。", "tip": "“涨 15% 再跌 10%”不等于涨 5%。跌是在涨过之后的基数上算的，复合结果一定小于直接相减。", "hard": "干扰项 2.5% 与 3.5% 只差 1 个百分点，必须老实相乘，靠感觉估很容易错。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市高新技术产业产值比上年增长约多少亿元（　）", "data": "【材料】2025 年某市高新技术产业产值 5600 亿元，比上年增长 12%。", "options": ["560 亿元", "600 亿元", "672 亿元", "700 亿元"], "answer": ["B"], "method": "已知现期求增长量：\n① 基期＝5600÷1.12＝5000；\n② 增长量＝5600−5000＝600。\n也可用 5600×12%÷1.12≈600。", "explain": "5600÷1.12＝5000，5600−5000＝600 亿元，选 B。", "tip": "不能直接 5600×12%＝672（那是拿现期当基期）。问“增长量”必须先用 1＋r 还原基期。", "hard": "干扰项 672 是典型错算；560 是“5000×12% 但基期抄错”的近似错值，两个都要防。"}, {"type": "applied", "level": "基础", "stem": "2024 年该县旅游收入约为（　）", "data": "【材料】2025 年某县实现旅游收入 86.4 亿元，同比增长 8%。", "options": ["80.0 亿元", "82.4 亿元", "78.0 亿元", "86.4 亿元"], "answer": ["A"], "method": "求基期量：\n① 基期＝现期÷（1＋r）；\n② 86.4÷1.08；\n③ 1.08×80＝86.4，故为 80.0 亿元。", "explain": "86.4÷1.08＝80.0，选 A。", "tip": "求基期一定要除（1＋r），不能用“现期×（1−r）”或“现期−现期×r”草草相减。", "hard": "干扰项 82.4 来自 86.4×（1−0.08）附近的错算，数值很接近，务必用除法。"}, {"type": "applied", "level": "基础", "stem": "2025 年该省第三产业增加值占 GDP 的比重约为（　）", "data": "【材料】2025 年某省 GDP 为 62000 亿元，其中第三产业增加值 34100 亿元。", "options": ["50%", "53%", "55%", "58%"], "answer": ["C"], "method": "比重＝部分÷总体：\n① 34100÷62000；\n② 62000×55%＝34100；\n③ 故为 55%。", "explain": "34100÷62000＝0.55＝55%，选 C。", "tip": "用“总体×选项”反验最快：62000×55%＝34100，一步到位。", "hard": "选项间隔 2—3 个百分点，若把 34100 抄成 33100 就会偏到 53%，抄数要仔细。"}, {"type": "applied", "level": "进阶", "stem": "2025 年高新技术产业增加值占规上工业比重比上年提高约（　）", "data": "【材料】2024 年某市高新技术产业增加值占规上工业增加值比重为 32%。2025 年该市规上工业增加值增长 6%，高新技术产业增加值增长 14%。", "options": ["1.6 个百分点", "2.0 个百分点", "2.2 个百分点", "2.4 个百分点"], "answer": ["D"], "method": "两期比重差：\n① 新比重＝0.32×1.14÷1.06；\n② 0.32×1.14＝0.3648，0.3648÷1.06≈0.3442；\n③ 提高＝34.42%−32%≈2.4 个百分点。", "explain": "0.32×1.14÷1.06≈34.4%，比 32% 提高约 2.4 个百分点，选 D。", "tip": "部分增速（14%）快于总体（6%），比重上升；升幅要用“新比重−旧比重”，不是两者增速相减。", "hard": "干扰项 2.0 来自“8%×32%≈2.6 再凭感觉取整”，正确算法只走两期比重公式。"}, {"type": "applied", "level": "基础", "stem": "该市地铁运营里程的年均增长量约为（　）", "data": "【材料】某市地铁运营里程 2019 年为 360 公里，2024 年为 860 公里。", "options": ["80 公里", "90 公里", "100 公里", "120 公里"], "answer": ["C"], "method": "年均增长量＝（末期−初期）÷年数差：\n① 860−360＝500；\n② 年数＝2024−2019＝5；\n③ 500÷5＝100。", "explain": "（860−360）÷5＝100 公里，选 C。", "tip": "年数用年份差 5，别用 6；分子是总增量 500，别直接用末期 860。", "hard": "选项 80/90/100/120 都在同一量级，年数或分子抄错就会串位。"}, {"type": "applied", "level": "基础", "stem": "2025 年 A 产品出口额约是 B 产品的（　）", "data": "【材料】2025 年某市 A 产品出口额为 240 亿美元，B 产品出口额为 75 亿美元。", "options": ["3.2 倍", "2.8 倍", "3.0 倍", "3.6 倍"], "answer": ["A"], "method": "倍数＝A÷B：\n① 240÷75；\n② 75×3＝225，余 15；\n③ 15÷75＝0.2，合计 3.2 倍。", "explain": "240÷75＝3.2，选 A。", "tip": "问“A 是 B 的几倍”用 A÷B；“A 比 B 多几倍”才要再减 1。", "hard": "干扰项 2.8 与 3.2 相差不大，若把 240 看成 225 就会偏到 3.0，先算整数部分再补小数。"}, {"type": "applied", "level": "基础", "stem": "该市平均每个公园新增绿化面积约为（　）", "data": "【材料】2025 年某市新增绿化面积 960 公顷，涉及 24 个新建公园。", "options": ["28 公顷", "32 公顷", "36 公顷", "40 公顷"], "answer": ["D"], "method": "平均数＝总量÷份数：\n① 960÷24；\n② 24×40＝960；\n③ 故为 40 公顷。", "explain": "960÷24＝40 公顷，选 D。", "tip": "平均数题先确认“份数”是公园数 24，别把面积当份数。", "hard": "960÷24 可以先把两边都约 24：960÷24＝40，一步到位；硬除容易把 36 当答案。"}, {"type": "applied", "level": "基础", "stem": "2023 年该市快递业务量约为（　）", "data": "【材料】某市 2025 年快递业务量为 12.6 亿件，比 2023 年增长 40%。", "options": ["9.0 亿件", "8.4 亿件", "7.6 亿件", "10.2 亿件"], "answer": ["A"], "method": "跨期求基期：\n① 基期＝现期÷（1＋总增速）；\n② 12.6÷1.4；\n③ 1.4×9＝12.6，故为 9.0 亿件。", "explain": "12.6÷1.4＝9.0 亿件，选 A。", "tip": "题目给的是“比 2023 年增长 40%”，直接除 1.4 即可，不必逐年拆算。", "hard": "干扰项 10.2 来自 12.6×0.8 附近的错算；记住基期＝现期÷（1＋r）。"}]}, {"set": 4, "date": "2026-10-01", "session": "day", "title": "资料分析速算训练 · 第 4 批（首数直除 / 增长率与增长量 / 间隔增长 / 年均增长 / 两期比重差 / 倍数与平均数 / 化分数）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "估算 4862 ÷ 1.24，结果最接近（　）", "options": ["3920", "4350", "3610", "4120"], "answer": ["A"], "method": "首数直除：48÷1.24≈38~39，量级约 3900；或用 1/1.24≈0.806，4862×0.806≈3920。", "explain": "4862÷1.24≈3920.97，取 3920，选 A。", "tip": "除法别做成乘法（4862×1.24≈6029 是常见错算）。", "hard": "结果应略小于 4862；4350 是错算干扰项。"}, {"type": "pure", "level": "基础", "stem": "4200 的 3.7% 约为（　）", "options": ["155", "15.5", "1550", "1.55"], "answer": ["A"], "method": "3.7%=0.037，4200×0.037=4200×37÷1000=155.4。", "explain": "约 155.4，取 155，选 A。", "tip": "百分号换算别漏一位：3.7% 是 0.037。", "hard": "15.5 是漏一位小数的结果；先定量级再选。"}, {"type": "pure", "level": "基础", "stem": "5/7 约等于（　）", "options": ["57.1%", "71.4%", "66.7%", "77.8%"], "answer": ["B"], "method": "1/7≈14.3%，5/7≈5×14.3%≈71.4%。", "explain": "5÷7≈0.7143，即 71.4%，选 B。", "tip": "常用化分数：1/7≈14.3%、1/6≈16.7%、1/9≈11.1%、1/8=12.5%。", "hard": "57.1% 是 4/7，易与 5/7 混。"}, {"type": "pure", "level": "基础", "stem": "某指标由 240 增长到 300，增长率为（　）", "options": ["25%", "20%", "30%", "12.5%"], "answer": ["A"], "method": "增长率=(现期−基期)÷基期=(300−240)÷240=60÷240=25%。", "explain": "60÷240=25%，选 A。", "tip": "分母一定是基期（240）。", "hard": "20% 是用 60÷300 的错算（分母用成现期）。"}, {"type": "pure", "level": "进阶", "stem": "某量第一年增长 20%，第二年增长 25%，两年合计增长（　）", "options": ["45%", "20%", "50%", "55%"], "answer": ["C"], "method": "间隔增长率 r=r₁+r₂+r₁×r₂=20%+25%+20%×25%=45%+5%=50%。", "explain": "1.20×1.25=1.50，两年共增长 50%，选 C。", "tip": "两年增长不能简单相加，要补乘积项。", "hard": "45% 是漏掉乘积项 5% 的干扰项。"}, {"type": "pure", "level": "进阶", "stem": "某量两年共增长 69%，其中第一年增长 30%，第二年增长（　）", "options": ["30%", "39%", "25%", "33%"], "answer": ["A"], "method": "倍数法：1+r₂=(1+69%)÷(1+30%)=1.69÷1.30=1.30，故 r₂=30%。", "explain": "1.69÷1.3=1.3，第二年增长 30%，选 A。", "tip": "用“1+总增长”除“1+已知年增长”。", "hard": "39% 是 69%−30% 直接相减的错算。"}, {"type": "pure", "level": "基础", "stem": "某量 2019 年 120，2024 年 270，2019—2024 年年均增长量为（　）", "options": ["30", "25", "37.5", "50"], "answer": ["A"], "method": "年均增长量=(270−120)÷(2024−2019)=150÷5=30。", "explain": "150÷5=30，选 A。", "tip": "年份差=末年−首年=5。", "hard": "37.5 是 150÷4 的错算。"}, {"type": "pure", "level": "进阶", "stem": "某部分占比由 25% 上升到 30%，则占比变化（　）", "options": ["上升 35%", "下降 5 个百分点", "上升 3 个百分点", "上升 5 个百分点"], "answer": ["D"], "method": "比重变化用百分点：30%−25%=+5 个百分点。", "explain": "上升 5 个百分点，选 D。", "tip": "比重变化量用“百分点”，是两个比重相减。", "hard": "“上升 35%”把百分点当成增长率（实为 +20%）。"}, {"type": "pure", "level": "基础", "stem": "A=1.26 万，B=0.42 万，A 是 B 的（　）倍", "options": ["2", "3", "4", "0.33"], "answer": ["B"], "method": "单位相同直接相除：1.26÷0.42=3。", "explain": "1.26÷0.42=3，选 B。", "tip": "“A 是 B 的几倍”=A÷B。", "hard": "0.33 是 B÷A 的倒算。"}, {"type": "pure", "level": "基础", "stem": "五个数据 82、91、78、85、94 的平均数为（　）", "options": ["86", "85", "87", "88"], "answer": ["A"], "method": "先求和 430，再除以项数 5：430÷5=86。", "explain": "430÷5=86，选 A。", "tip": "平均数=总量÷项数。", "hard": "误用 430÷4 会明显偏离。"}, {"type": "pure", "level": "进阶", "stem": "某项指标由 1.05 调整为 1.10，增幅约为（　）", "options": ["4.5%", "4.8%", "3.3%", "5.0%"], "answer": ["B"], "method": "增幅=(1.10−1.05)÷1.05=0.05÷1.05≈4.76%≈4.8%。", "explain": "约 4.8%，选 B。", "tip": "分母是原来的 1.05。", "hard": "4.5% 是 0.05÷1.10 的错算（分母用错）。"}, {"type": "pure", "level": "进阶", "stem": "某量 4 年翻了一番（共增长 100%），年均增长率约为（　）", "options": ["15%", "25%", "19%", "20%"], "answer": ["C"], "method": "4 年后变为 2 倍，年均=2^(1/4)−1≈1.189−1=18.9%≈19%。", "explain": "约 18.9%，选 C。", "tip": "年均增长率要“开方”，不能总增长除以年数。", "hard": "25% 是 100%÷4 的错算。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市新能源汽车产量同比增长（　）", "data": "【材料】2024 年某市新能源汽车产量 40 万辆，2025 年增至 48 万辆。", "options": ["16.7%", "20%", "8%", "120%"], "answer": ["B"], "method": "增长率=(48−40)÷40=8÷40=20%。", "explain": "8÷40=20%，选 B。", "tip": "分母用基期（40 万辆）。", "hard": "16.7% 是 8÷48 的错算。"}, {"type": "applied", "level": "基础", "stem": "2019—2024 年该市常住人口年均增长量为（　）", "data": "【材料】某市常住人口 2019 年 620 万人，2024 年 680 万人。", "options": ["10 万", "12 万", "15 万", "60 万"], "answer": ["B"], "method": "年均增长量=(680−620)÷(2024−2019)=60÷5=12（万人/年）。", "explain": "60÷5=12 万，选 B。", "tip": "年份差为 5。", "hard": "15 万是 60÷4 的错算。"}, {"type": "applied", "level": "基础", "stem": "该公司线上渠道销售额占比约为（　）", "data": "【材料】某公司全年销售额 5000 万元，其中线上渠道 1800 万元。", "options": ["24%", "28%", "36%", "64%"], "answer": ["C"], "method": "占比=部分÷整体=1800÷5000=0.36=36%。", "explain": "36%，选 C。", "tip": "求占比用“部分÷整体”。", "hard": "64% 是线下占比（1−36%）。"}, {"type": "applied", "level": "进阶", "stem": "2025 年该产品销量比 2023 年增长（　）", "data": "【材料】某产品 2023 年销量 100 万件；2024 年比 2023 年增长 20%；2025 年比 2024 年增长 15%。", "options": ["35%", "38%", "40%", "5%"], "answer": ["B"], "method": "1.20×1.15=1.38，即增长 38%。", "explain": "1.38−1=38%，选 B。", "tip": "间隔增长率=r₁+r₂+r₁r₂。", "hard": "35% 是简单相加，漏了 20%×15%=3%。"}, {"type": "applied", "level": "进阶", "stem": "2025 年该市数字经济增加值占 GDP 比重比上年（　）", "data": "【材料】某市 2024 年 GDP 8000 亿元，其中数字经济 2000 亿元；2025 年 GDP 9000 亿元，其中数字经济 2700 亿元。", "options": ["上升 5 个百分点", "上升 3 个百分点", "上升 35%", "下降 5 个百分点"], "answer": ["A"], "method": "新比重 2700÷9000=30%，旧比重 2000÷8000=25%，差 +5 个百分点。", "explain": "上升 5 个百分点，选 A。", "tip": "比重变化用“百分点”表示。", "hard": "“上升 35%”是把比重值当成了增长率。"}, {"type": "applied", "level": "基础", "stem": "该企业上半年月均产量为（　）", "data": "【材料】某企业 1—6 月产量依次为 22、25、28、24、26、25（万台）。", "options": ["24 万台", "26 万台", "27 万台", "25 万台"], "answer": ["D"], "method": "求和 150，月均=150÷6=25 万台。", "explain": "150÷6=25 万台，选 D。", "tip": "平均数=总量÷月数。", "hard": "按 5 个月除可得 30，属漏项错算。"}, {"type": "applied", "level": "基础", "stem": "使用该功能的用户约为（　）", "data": "【材料】某平台年度活跃用户约 3.5 亿人，调查显示约七分之一的用户使用过某项新功能。", "options": ["3500 万", "5000 万", "7000 万", "2500 万"], "answer": ["B"], "method": "3.5 亿×1/7=0.5 亿=5000 万。", "explain": "5000 万，选 B。", "tip": "1/7≈14.3%，3.5 亿的 1/7 即 5000 万。", "hard": "3500 万是 3.5 亿×1/10 的错算。"}, {"type": "applied", "level": "进阶", "stem": "2021—2025 年该县农村居民人均可支配收入年均增长率约为（　）", "data": "【材料】某县农村居民人均可支配收入 2021 年 1.6 万元，2025 年 2.56 万元（共 4 年）。", "options": ["10%", "16%", "25%", "12.5%"], "answer": ["D"], "method": "倍数=2.56÷1.6=1.6，4 年年均=1.6^(1/4)−1≈1.125−1≈12.5%。", "explain": "约 12.5%，选 D。", "tip": "年均增长率=（末年/首年）^(1/年数)−1。", "hard": "16% 混淆倍数与增速；25% 是 1÷4 的错算。"}]}, {"set": 5, "date": "2026-10-02", "session": "am", "title": "资料分析速算训练 · 第 5 批（首数直除 / 估算范围 / 增长率与增长量 / 间隔增长率 / 年均增长量 / 年均增长率 / 两期比重差 / 倍数与平均数 / 化分数 / 百分数加减）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "4128 ÷ 1.37 ≈（　）", "options": ["2810", "3013", "3210", "3510"], "answer": ["B"], "method": "首数直除：1.37 × 3000 = 4110，略小于 4128，故结果略大于 3000。", "explain": "1.37×3000=4110＜4128，商约 3013，选 B。", "tip": "先定“整数档”，再用首数微调。", "hard": "3510 是 4128÷1.18 之类的错算。"}, {"type": "pure", "level": "中等", "stem": "7382 ÷ 0.842 ≈（　）", "options": ["7967", "8367", "8767", "9167"], "answer": ["C"], "method": "0.842 × 8760 = 7375.9，接近 7382，故商约 8767。", "explain": "7382÷0.842≈8767，选 C。", "tip": "除以小于 1 的数，结果比原数大。", "hard": "7967 是 7382÷0.926 的错算。"}, {"type": "pure", "level": "基础", "stem": "2160 的 1/7 约为（　）", "options": ["289", "299", "309", "319"], "answer": ["C"], "method": "化分数：1/7≈14.3%，2160÷7≈308.6。", "explain": "2160÷7≈308.6，取 309，选 C。", "tip": "记牢 1/7≈14.3%、1/8=12.5%、1/9≈11.1%。", "hard": "319 是 2160÷6.77 之类的错算。"}, {"type": "pure", "level": "中等", "stem": "某商品单价先上涨 20%，后又下降 20%，则最终价格与原价比（　）", "options": ["不变", "下降 4%", "上涨 4%", "下降 2%"], "answer": ["B"], "method": "1×(1+20%)×(1−20%)=1×1.2×0.8=0.96，即下降 4%。", "explain": "1.2×0.8=0.96，比原价少 4%，选 B。", "tip": "先涨后降同一比例，最终必低于原价（乘数 1−x²）。", "hard": "误以为“一涨一降正好抵消”。"}, {"type": "pure", "level": "基础", "stem": "某市 GDP 由 2019 年的 800 亿元增至 2024 年的 1200 亿元，年均增长量约为（　）亿元", "options": ["60", "80", "100", "120"], "answer": ["A"], "method": "年均增长量=(末期−初期)÷年数差=(1200−800)÷(2024−2019)=400÷5=80。", "explain": "400÷5=80 亿元，选 A。", "tip": "年数差用“末年−首年”，不是“年份个数”。", "hard": "误用 400÷6≈66.7。"}, {"type": "pure", "level": "基础", "stem": "3840 约是 1280 的（　）倍", "options": ["2.8", "3", "3.2", "4"], "answer": ["B"], "method": "3840÷1280=3。", "explain": "3840÷1280=3，选 B。", "tip": "倍数＝前者÷后者，注意谁比谁。", "hard": "4 是把 1280×3≈3840 与“约 4 倍”混。"}, {"type": "pure", "level": "基础", "stem": "某企业 5 个部门人数分别为 48、52、45、55、50 人，则平均人数为（　）", "options": ["48", "49", "50", "51"], "answer": ["C"], "method": "总数=48+52+45+55+50=250，平均=250÷5=50。", "explain": "250÷5=50，选 C。", "tip": "平均数=总数÷个数。", "hard": "以最大最小取中值易误判。"}, {"type": "pure", "level": "中等", "stem": "5936 ÷ 7.9 ≈（　）", "options": ["651", "701", "751", "801"], "answer": ["C"], "method": "7.9 × 750 = 5925，接近 5936，故商约 751。", "explain": "5936÷7.9≈751，选 C。", "tip": "用 8×750=6000 快速框定范围。", "hard": "801 是 5936÷7.4 的错算。"}, {"type": "pure", "level": "基础", "stem": "39.8 × 5.12 ≈（　）", "options": ["164", "184", "204", "224"], "answer": ["C"], "method": "估算范围：40×5=200，40×5.12=204.8，故约 204。", "explain": "≈40×5.12=204.8，取 204，选 C。", "tip": "把 39.8 近似为 40，误差极小。", "hard": "224 是把 5.12 当成 5.6 的错算。"}, {"type": "pure", "level": "中等", "stem": "某地游客人数 2023 年比 2022 年增长 10%，2024 年比 2023 年增长 20%，则 2024 年比 2022 年增长约（　）", "options": ["22%", "30%", "32%", "34%"], "answer": ["C"], "method": "间隔增长率：1.1 × 1.2 = 1.32，即增长 32%。", "explain": "1.1×1.2=1.32，增长 32%，选 C。", "tip": "间隔增长率≠两期增长率相加（10%+20%=30% 是干扰项）。", "hard": "30% 是把两期增长率直接相加的错算。"}, {"type": "pure", "level": "基础", "stem": "3/8 用百分数表示约为（　）", "options": ["33.3%", "35.0%", "37.5%", "42.9%"], "answer": ["C"], "method": "化分数：1/8=12.5%，故 3/8=37.5%。", "explain": "3÷8=0.375=37.5%，选 C。", "tip": "1/8=12.5% 是常用分数记忆点。", "hard": "33.3% 是 1/3 的值。"}, {"type": "pure", "level": "中等", "stem": "某指标由 100 增长到 121，这两年的年均增长率约为（　）", "options": ["9.5%", "10%", "11%", "21%"], "answer": ["B"], "method": "年均增长率：1×(1+r)²=1.21，则 (1+r)²=1.21，1+r=1.1，r=10%。", "explain": "开平方：√1.21=1.1，故年均增长 10%，选 B。", "tip": "两年翻成 1.21，年均即 10%（1.1²=1.21）。", "hard": "21% 是把总增长率直接当成年均增长率。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市快递业务量同比增长（　）", "data": "【材料】2024 年某市快递业务量 12.5 亿件，2025 年增至 15 亿件。", "options": ["16.7%", "20%", "25%", "120%"], "answer": ["B"], "method": "增长率=(15−12.5)÷12.5=2.5÷12.5=20%。", "explain": "2.5÷12.5=20%，选 B。", "tip": "分母用基期（12.5 亿件）。", "hard": "16.7% 是 2.5÷15 的错算。"}, {"type": "applied", "level": "基础", "stem": "2025 年该地财政收入比上年增加（　）亿元", "data": "【材料】某地 2024 年财政收入 320 亿元，2025 年增至 368 亿元。", "options": ["38", "44", "48", "52"], "answer": ["C"], "method": "增长量=368−320=48 亿元。", "explain": "368−320=48，选 C。", "tip": "“增加多少”求的是增长量（减法），不是增长率。", "hard": "误用 368×15%≈55。"}, {"type": "applied", "level": "基础", "stem": "该校女生人数约占全校学生的（　）", "data": "【材料】某校共有学生 1200 人，其中女生 450 人。", "options": ["33.3%", "35.0%", "37.5%", "40.0%"], "answer": ["C"], "method": "占比=450÷1200=0.375=37.5%。", "explain": "450÷1200=37.5%，选 C。", "tip": "“占比”用部分÷总体。", "hard": "33.3% 是 400÷1200 的值。"}, {"type": "applied", "level": "基础", "stem": "该公司人均创收约为（　）万元", "data": "【材料】某公司全年营业收入 9600 万元，共有员工 120 人。", "options": ["60", "70", "80", "90"], "answer": ["C"], "method": "平均数=9600÷120=80 万元。", "explain": "9600÷120=80，选 C。", "tip": "人均＝总量÷人数。", "hard": "90 是 9600÷107 之类的错算。"}, {"type": "applied", "level": "基础", "stem": "甲地旅游收入约是乙地的（　）倍", "data": "【材料】甲地年旅游收入 45 亿元，乙地年旅游收入 9 亿元。", "options": ["4", "4.5", "5", "5.5"], "answer": ["C"], "method": "倍数=45÷9=5。", "explain": "45÷9=5，选 C。", "tip": "倍数＝前者÷后者。", "hard": "4 是 36÷9 的错算。"}, {"type": "applied", "level": "中等", "stem": "该市常住人口 2020—2025 年的年均增长量约为（　）万人", "data": "【材料】某市常住人口 2020 年为 500 万人，2025 年为 550 万人。", "options": ["8", "10", "12", "15"], "answer": ["B"], "method": "年均增长量=(550−500)÷(2025−2020)=50÷5=10 万人。", "explain": "50÷5=10，选 B。", "tip": "年数差为 5，不要用 6。", "hard": "8 是把 50÷6 四舍五入的错算。"}, {"type": "applied", "level": "中等", "stem": "2025 年该市第三产业占比比上年（　）", "data": "【材料】2024 年某市 GDP 1000 亿元，其中第三产业 550 亿元；2025 年 GDP 1100 亿元，其中第三产业 638 亿元。", "options": ["提高 2 个百分点", "提高 3 个百分点", "下降 3 个百分点", "提高 5 个百分点"], "answer": ["B"], "method": "2024 年占比=550÷1000=55%；2025 年占比=638÷1100=58%；提高 58%−55%=3 个百分点。", "explain": "55%→58%，提高 3 个百分点，选 B。", "tip": "比重变化用“百分点”表述，先分别算出两期比重再相减。", "hard": "“5 个百分点”是把 550 与 638 的差直接当成比重差。"}, {"type": "applied", "level": "中等", "stem": "该县 2024 年茶叶产量比 2022 年增长约（　）", "data": "【材料】某县茶叶产量 2023 年比 2022 年增长 25%，2024 年比 2023 年增长 20%。", "options": ["45%", "48%", "50%", "55%"], "answer": ["C"], "method": "间隔增长率：1.25 × 1.2 = 1.5，即增长 50%。", "explain": "1.25×1.2=1.5，增长 50%，选 C。", "tip": "间隔两年用乘法相乘，不是相加（25%+20%=45% 是干扰项）。", "hard": "45% 是把两期增长率相加的错算。"}]}, {"set": 6, "date": "2026-10-03", "session": "day", "title": "资料分析速算训练 · 第 6 批（首数直除 / 估算与范围 / 增长率与增长量 / 间隔增长率 / 年均增长量 / 年均增长率 / 两期比重差 / 倍数与平均数 / 化分数 / 百分数加减）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "5236 ÷ 1.28 ≈（　）", "options": ["3890", "4091", "4290", "4520"], "answer": ["B"], "method": "首数直除：1.28 × 4000 = 5120，略小于 5236，故结果略大于 4000。再试 1.28×4090=5235.2，几乎相等。", "explain": "1.28×4090=5235.2，接近 5236，商约 4091，选 B。", "tip": "先定“整数档”（4000），再用首数微调，不必精确长除。", "hard": "4520 是用 1.16 之类除数算出的，注意别把除数看错。"}, {"type": "pure", "level": "基础", "stem": "7189 ÷ 0.923 ≈（　）", "options": ["7490", "7790", "8090", "8390"], "answer": ["B"], "method": "0.923 × 7800 = 7199.4，略大于 7189，故商略小于 7800，约 7790。", "explain": "0.923×7790≈7189，选 B。", "tip": "除以小于 1 的数，结果比原数大，可先排除 7490 以下的项。", "hard": "7490 是把结果算小了（误按 ÷1.0 估）。"}, {"type": "pure", "level": "中等", "stem": "某地 2024 年财政收入 268 亿元，2025 年为 321 亿元，2025 年增长率约为（　）", "options": ["16.5%", "19.8%", "23.1%", "26.4%"], "answer": ["B"], "method": "增长率 =（现期−基期）÷基期 =（321−268）÷268 = 53÷268。53÷268≈0.198（把 268 看成 265，53÷265≈20%）。", "explain": "(321−268)/268=53/268≈19.8%，选 B。", "tip": "分母永远是“基期（去年）”而不是现期，这是最常见的错。", "hard": "53÷321≈16.5% 就是错把分母当成现期，恰好对应 A，别上当。"}, {"type": "pure", "level": "中等", "stem": "某市 2025 年快递业务量 4.86 亿件，同比增长 8%，则比上年约增加（　）亿件", "options": ["0.30", "0.36", "0.42", "0.48"], "answer": ["B"], "method": "增长量 = 现期÷(1+r) × r。4.86÷1.08 = 4.5；4.5×8% = 0.36。", "explain": "4.86÷1.08=4.5，再乘 8% 得 0.36 亿件，选 B。", "tip": "增长量要用“基期×增长率”，不能拿现期直接乘 8%（4.86×8%=0.389，会滑向干扰项）。", "hard": "4.86×8%≈0.39 是常见错算，对应 C 附近。"}, {"type": "pure", "level": "中等", "stem": "某指标 2023 年比 2022 年增长 10%，2024 年比 2023 年增长 20%，则 2024 年比 2022 年增长约（　）", "options": ["28%", "30%", "32%", "34%"], "answer": ["C"], "method": "间隔增长率 =（1+r₁)(1+r₂)−1 = 1.1×1.2−1 = 1.32−1 = 0.32。", "explain": "1.1×1.2=1.32，即增长 32%，选 C。", "tip": "两段增速不能直接相加（10%+20%=30% 是错的），必须“乘起来”。", "hard": "30% 是“直接相加”的错算，是最常见干扰项。"}, {"type": "pure", "level": "基础", "stem": "某市 GDP 由 2019 年的 520 亿元增至 2024 年的 895 亿元，年均增长量约为（　）亿元", "options": ["65", "70", "75", "80"], "answer": ["C"], "method": "年均增长量 =（末期−初期）÷年数差 =（895−520）÷(2024−2019) = 375÷5 = 75。", "explain": "375÷5=75 亿元，选 C。", "tip": "年数差用“末年−首年”（5 年），不是年份个数（2024−2019 有 6 个年份）。", "hard": "375÷6≈62.5 是错用“年份个数”的典型。"}, {"type": "pure", "level": "进阶", "stem": "某地 GDP 由 2020 年的 100 亿元增至 2024 年的 146.4 亿元，年均增长率约为（　）", "options": ["8%", "10%", "12%", "14%"], "answer": ["B"], "method": "年均增长率 =(末期/初期)^(1/n)−1。146.4/100=1.464，n=4。用熟值：1.1⁴=1.4641≈1.464。", "explain": "1.1⁴=1.4641，故年均增长约 10%，选 B。", "tip": "记牢 1.1²=1.21、1.1³=1.331、1.1⁴=1.4641，很多题可直接“认出来”。", "hard": "用“总增速÷年数”（46.4%/4≈11.6%）会滑向 12%。"}, {"type": "pure", "level": "进阶", "stem": "某部分增速为 15%，整体增速为 10%，则该部分占整体的比重与上年相比（　）", "options": ["上升，且变化不足 5 个百分点", "上升，且变化超过 5 个百分点", "下降，且变化不足 5 个百分点", "下降，且变化超过 5 个百分点"], "answer": ["A"], "method": "两期比重差：部分增速 a > 整体增速 b → 比重上升；变化幅度一定小于 |a−b| = 5 个百分点。", "explain": "a=15%>b=10%，比重上升；变化量小于 5 个百分点，选 A。", "tip": "口诀：部分比整体快，比重就上升；且升降幅度必小于增速之差。", "hard": "“超过 5 个百分点”永远错——这是个可直接秒杀的结论。"}, {"type": "pure", "level": "基础", "stem": "3840 约是 1280 的（　）倍", "options": ["2.5", "2.8", "3", "3.2"], "answer": ["C"], "method": "3840÷1280 = 3（1280×3=3840）。", "explain": "1280×3=3840，故是 3 倍，选 C。", "tip": "倍数问题先看能否“整数倍”，一眼可定。", "hard": "3.2 是把 3840 看成 4096 之类的错算。"}, {"type": "pure", "level": "基础", "stem": "某市 2025 年完成投资 1260 亿元，涉及项目 350 个，平均每个项目投资约（　）亿元", "options": ["3.2", "3.6", "4.0", "4.4"], "answer": ["B"], "method": "平均数 = 总量÷个数 = 1260÷350。350×3.6=1260。", "explain": "1260÷350=3.6 亿元，选 B。", "tip": "350×3=1050，还差 210，210÷350=0.6，所以是 3.6。", "hard": "4.0 是 1400÷350 的错算。"}, {"type": "pure", "level": "基础", "stem": "3648 的 1/7 约为（　）", "options": ["501", "521", "541", "561"], "answer": ["B"], "method": "化分数：1/7≈14.3%，3648÷7≈521.1。", "explain": "3648÷7≈521，选 B。", "tip": "记牢 1/7≈14.3%、1/8=12.5%、1/9≈11.1%。", "hard": "501 是 3507÷7 的错算。"}, {"type": "pure", "level": "基础", "stem": "某厂上半年产值 480 万元，下半年比上半年多 25%，全年产值约为（　）万元", "options": ["1020", "1080", "1140", "1200"], "answer": ["B"], "method": "下半年 = 480×(1+25%) = 600；全年 = 480+600 = 1080。", "explain": "480+600=1080 万元，选 B。", "tip": "“多 25%”是乘 1.25，不是加 25 万。", "hard": "1020 是漏算了下半年的高出部分。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某省规模以上工业增加值 1.86 万亿元，同比增长 6.2%。", "stem": "该省 2024 年规模以上工业增加值约为（　）万亿元", "options": ["1.68", "1.75", "1.82", "1.89"], "answer": ["B"], "method": "基期 = 现期÷(1+r) = 1.86÷1.062。1.86÷1.06≈1.755。", "explain": "1.86÷1.062≈1.75 万亿元，选 B。", "tip": "“已知现期和增速，求基期”用除法，别用 1.86×(1−6.2%)（那会偏小）。", "hard": "1.86×0.938≈1.745 与正确答案相近，但严格说是错式；正确解更稳。"}, {"type": "applied", "level": "基础", "data": "【材料】某市 2025 年接待游客 3800 万人次，比 2020 年增长 90%。", "stem": "该市 2020 年接待游客约为（　）万人次", "options": ["1900", "2000", "2100", "2200"], "answer": ["B"], "method": "基期 = 现期÷(1+r) = 3800÷1.9 = 2000。", "explain": "3800÷1.9=2000 万人次，选 B。", "tip": "“比……增长 90%”即现期是基期的 1.9 倍。", "hard": "3800×0.9=3420 是把“增长率”当“现期占比”的错算。"}, {"type": "applied", "level": "基础", "data": "【材料】2025 年某企业营业收入 5.4 亿元，净利润 0.648 亿元。", "stem": "该企业 2025 年净利率约为（　）", "options": ["10%", "11%", "12%", "13%"], "answer": ["C"], "method": "净利率 = 净利润÷营业收入 = 0.648÷5.4。5.4×0.12=0.648。", "explain": "0.648÷5.4=0.12=12%，选 C。", "tip": "“率”类问题：部分÷整体，注意分子分母别颠倒。", "hard": "5.4÷0.648≈8.33 是分子分母颠倒的错算。"}, {"type": "applied", "level": "基础", "data": "【材料】2025 年某地区 A 项收入 320 亿元，B 项收入 480 亿元。", "stem": "A 项收入占 A、B 两项合计的比重约为（　）", "options": ["36%", "40%", "44%", "48%"], "answer": ["B"], "method": "比重 = A÷(A+B) = 320÷800 = 0.4。", "explain": "320÷(320+480)=320÷800=40%，选 B。", "tip": "“占……合计的比重”，分母是合计，不是另一项。", "hard": "320÷480≈66.7% 是只拿 B 当分母的错算。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某国货物出口 2.4 万亿元，进口 1.9 万亿元。", "stem": "该国 2025 年货物贸易顺差占出口额的比重约为（　）", "options": ["18.5%", "20.8%", "23.2%", "25.6%"], "answer": ["B"], "method": "顺差 = 出口−进口 = 2.4−1.9 = 0.5；占出口比重 = 0.5÷2.4≈20.8%。", "explain": "0.5÷2.4≈0.208=20.8%，选 B。", "tip": "先算顺差（0.5），再除以“出口额”2.4，别除以进口额。", "hard": "0.5÷1.9≈26.3% 是把分母当成进口额的错算。"}, {"type": "applied", "level": "中等", "data": "【材料】某地 2025 年建成 5G 基站 12.5 万个，2020 年为 4 万个。", "stem": "2025 年该地基站数量比 2020 年增长约（　）", "options": ["180%", "212.5%", "240%", "280%"], "answer": ["B"], "method": "增长率 =（现期−基期）÷基期 =（12.5−4）÷4 = 8.5÷4 = 2.125。", "explain": "8.5÷4=2.125=212.5%，选 B。", "tip": "“增长百分之几”是相对基期，不是相对现期。", "hard": "8.5÷12.5=68% 是把分母当成现期的错算。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某市一般公共预算收入 920 亿元，其中税收收入 736 亿元，财政总收入同比增长 4%。", "stem": "2025 年该市税收收入占一般公共预算收入的比重约为（　）", "options": ["72%", "76%", "80%", "84%"], "answer": ["C"], "method": "比重 = 736÷920。920×0.8 = 736。", "explain": "736÷920=0.8=80%，选 C。", "tip": "同比增长 4% 是干扰信息；求“占比”与增速无关。", "hard": "若误用 (1+4%) 调整分子或分母，就会滑向 76% 或 84%。"}, {"type": "applied", "level": "进阶", "data": "【材料】2025 年前三季度某省社会消费品零售总额 1.2 万亿元，同比增长 5%；第四季度 0.5 万亿元，同比增长 8%。", "stem": "该省 2025 年全年社会消费品零售总额同比增速约为（　）", "options": ["5.0%", "5.9%", "6.5%", "7.0%"], "answer": ["B"], "method": "基期总量 = 1.2÷1.05 + 0.5÷1.08 ≈ 1.1429 + 0.4630 = 1.6059；现期 = 1.7。增速 = 1.7÷1.6059 − 1 ≈ 5.86%。", "explain": "1.7÷1.6059≈1.0586，即增长约 5.9%，选 B。", "tip": "混合增速不能简单取平均（(5%+8%)/2=6.5% 是错的），要在基期口径下加权。", "hard": "6.5% 恰是“直接平均”的错算，对应 C，是本题最大陷阱。"}]}, {"set": 7, "date": "2026-10-04", "session": "day", "title": "资料分析速算训练 · 第 7 批（首数直除 / 估算与范围 / 增长率与增长量 / 间隔增长率 / 年均增长量 / 年均增长率 / 两期比重差 / 倍数与平均数 / 化分数 / 百分数加减）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "6384 ÷ 1.28 ≈（　）", "options": ["4780", "4988", "5190", "5390"], "answer": ["B"], "method": "首数直除：1.28 × 5000 = 6400，略大于 6384，故商略小于 5000。再试 1.28×4988=6384.6，几乎相等。", "explain": "1.28×4988≈6384，商约 4988，选 B。", "tip": "先定“整数档”（5000），再往回收一点点，不必精确长除。", "hard": "5190 是把除数看成 1.23 之类算出的，注意除数别抄错。"}, {"type": "pure", "level": "基础", "stem": "8426 ÷ 0.917 ≈（　）", "options": ["8790", "8980", "9189", "9390"], "answer": ["C"], "method": "0.917 × 9200 = 8436.4，略大于 8426，故商略小于 9200，约 9189。", "explain": "0.917×9189≈8427，选 C。", "tip": "除以小于 1 的数，结果比原数大，可先排除 8790 以下的项。", "hard": "8790 是把结果算小了（误按 ÷1.0 估），是本题最大干扰项。"}, {"type": "pure", "level": "中等", "stem": "某市 2025 年 GDP 为 4270 亿元，2024 年为 3850 亿元，2025 年 GDP 增长率约为（　）", "options": ["8.9%", "10.9%", "12.9%", "14.9%"], "answer": ["B"], "method": "增长率 =（现期−基期）÷基期 =（4270−3850）÷3850 = 420÷3850。420÷3850≈0.109（把 3850 看成 3850，420÷3850≈10.9%）。", "explain": "(4270−3850)/3850=420/3850≈10.9%，选 B。", "tip": "分母永远是“基期（去年）”3850，而不是现期 4270，这是最常见的错。", "hard": "420÷4270≈9.8% 就是错把分母当成现期，恰好接近 A，别上当。"}, {"type": "pure", "level": "中等", "stem": "某县 2025 年电商交易额 6.72 亿元，同比增长 12%，则比上年约增加（　）亿元", "options": ["0.60", "0.72", "0.81", "0.90"], "answer": ["B"], "method": "增长量 = 现期÷(1+r) × r。6.72÷1.12 = 6.0；6.0×12% = 0.72。", "explain": "6.72÷1.12=6.0，再乘 12% 得 0.72 亿元，选 B。", "tip": "增长量要用“基期×增长率”，不能拿现期直接乘 12%（6.72×12%=0.806）。", "hard": "6.72×12%≈0.81 是常见错算，恰好对应 C，注意避坑。"}, {"type": "pure", "level": "中等", "stem": "某指标 2023 年比 2022 年增长 15%，2024 年比 2023 年增长 20%，则 2024 年比 2022 年增长约（　）", "options": ["35%", "38%", "41%", "44%"], "answer": ["B"], "method": "间隔增长率 =（1+r₁)(1+r₂)−1 = 1.15×1.20−1 = 1.38−1 = 0.38。", "explain": "1.15×1.20=1.38，即增长 38%，选 B。", "tip": "两段增速不能直接相加（15%+20%=35% 是错的），必须“乘起来”。", "hard": "35% 是“直接相加”的错算，是最常见干扰项，对应 A。"}, {"type": "pure", "level": "基础", "stem": "某地 GDP 由 2020 年的 380 亿元增至 2025 年的 680 亿元，年均增长量约为（　）亿元", "options": ["50", "60", "65", "75"], "answer": ["B"], "method": "年均增长量 =（末期−初期）÷年数差 =（680−380）÷(2025−2020) = 300÷5 = 60。", "explain": "300÷5=60 亿元，选 B。", "tip": "年数差用“末年−首年”（5 年），不是年份个数（2020—2025 有 6 个年份）。", "hard": "300÷6=50 是错用“年份个数”的典型，恰好对应 A。"}, {"type": "pure", "level": "进阶", "stem": "某市 GDP 由 2020 年的 100 亿元增至 2023 年的 172.8 亿元，年均增长率约为（　）", "options": ["15%", "18%", "20%", "22%"], "answer": ["C"], "method": "年均增长率 =(末期/初期)^(1/n)−1。172.8/100=1.728，n=3。用熟值：1.2³=1.728。", "explain": "1.2³=1.728，故年均增长约 20%，选 C。", "tip": "记牢 1.2²=1.44、1.2³=1.728、1.1⁴=1.4641，很多题可直接“认出来”。", "hard": "用“总增速÷年数”（72.8%/3≈24.3%）会滑向 22% 甚至更高，别用简单平均。"}, {"type": "pure", "level": "进阶", "stem": "某部分增速为 20%，整体增速为 8%，则该部分占整体的比重与上年相比（　）", "options": ["上升，且变化不足 12 个百分点", "上升，且变化超过 12 个百分点", "下降，且变化不足 12 个百分点", "下降，且变化超过 12 个百分点"], "answer": ["A"], "method": "两期比重差：部分增速 a > 整体增速 b → 比重上升；变化幅度一定小于 |a−b| = 12 个百分点。", "explain": "a=20%>b=8%，比重上升；变化量小于 12 个百分点，选 A。", "tip": "口诀：部分比整体快，比重就上升；且升降幅度必小于增速之差。", "hard": "“超过 12 个百分点”永远错——这是可直接秒杀的结论。"}, {"type": "pure", "level": "基础", "stem": "5820 约是 1455 的（　）倍", "options": ["3.5", "4", "4.5", "5"], "answer": ["B"], "method": "5820÷1455 = 4（1455×4=5820）。", "explain": "1455×4=5820，故是 4 倍，选 B。", "tip": "倍数问题先看能否“整数倍”，一眼可定。", "hard": "4.5 是把 5820 看成 6548 之类的错算。"}, {"type": "pure", "level": "基础", "stem": "某市 2025 年完成进出口 3360 亿元，涉及企业 840 家，平均每家企业进出口约（　）亿元", "options": ["3.2", "3.6", "4.0", "4.4"], "answer": ["C"], "method": "平均数 = 总量÷个数 = 3360÷840。840×4=3360。", "explain": "3360÷840=4.0 亿元，选 C。", "tip": "840×3=2520，还差 840，840÷840=1，所以是 4。", "hard": "4.4 是 3696÷840 的错算。"}, {"type": "pure", "level": "基础", "stem": "4032 的 1/8 约为（　）", "options": ["404", "454", "504", "554"], "answer": ["C"], "method": "化分数：1/8 = 12.5%，4032÷8 = 504。", "explain": "4032÷8=504，选 C。", "tip": "记牢 1/8=12.5%、1/7≈14.3%、1/9≈11.1%，能秒算。", "hard": "454 是 3632÷8 的错算，别把被除数看错。"}, {"type": "pure", "level": "基础", "stem": "某厂一季度产值 260 万元，二季度比一季度少 15%，上半年产值约为（　）万元", "options": ["441", "461", "481", "501"], "answer": ["C"], "method": "二季度 = 260×(1−15%) = 221；上半年 = 260+221 = 481。", "explain": "260+221=481 万元，选 C。", "tip": "“少 15%”是乘 0.85，不是减 15 万。", "hard": "441 是漏加了二季度那部分（只算了 260×1.7 之类的错式）。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某市接待游客 4500 万人次，同比增长 20%。", "stem": "该市 2024 年接待游客约为（　）万人次", "options": ["3600", "3750", "3900", "4050"], "answer": ["B"], "method": "基期 = 现期÷(1+r) = 4500÷1.2 = 3750。", "explain": "4500÷1.2=3750 万人次，选 B。", "tip": "“同比增长 20%”即现期是基期的 1.2 倍，求基期用除法。", "hard": "4500×(1−20%)=3600 是错用减法，恰好对应 A，是本题最大陷阱。"}, {"type": "applied", "level": "基础", "data": "【材料】某市 2025 年快递业务收入 960 亿元，比 2020 年增长 60%。", "stem": "该市 2020 年快递业务收入约为（　）亿元", "options": ["540", "570", "600", "630"], "answer": ["C"], "method": "基期 = 现期÷(1+r) = 960÷1.6 = 600。", "explain": "960÷1.6=600 亿元，选 C。", "tip": "“比 2020 年增长 60%”即现期是基期的 1.6 倍。", "hard": "960×0.6=576 是把“增长率”当“现期占比”的错算，落在 B 附近。"}, {"type": "applied", "level": "基础", "data": "【材料】2025 年某企业营业收入 7.2 亿元，净利润 0.9 亿元。", "stem": "该企业 2025 年净利率约为（　）", "options": ["10.0%", "11.5%", "12.5%", "13.5%"], "answer": ["C"], "method": "净利率 = 净利润÷营业收入 = 0.9÷7.2。7.2×0.125=0.9。", "explain": "0.9÷7.2=0.125=12.5%，选 C。", "tip": "“率”类问题：部分÷整体，分子分母别颠倒。", "hard": "7.2÷0.9=8（倍）是分子分母颠倒的错算，别当成率。"}, {"type": "applied", "level": "基础", "data": "【材料】2025 年某地区 A 项收入 360 亿元，B 项收入 540 亿元。", "stem": "A 项收入占 A、B 两项合计的比重约为（　）", "options": ["33%", "36%", "40%", "44%"], "answer": ["C"], "method": "比重 = A÷(A+B) = 360÷900 = 0.4。", "explain": "360÷(360+540)=360÷900=40%，选 C。", "tip": "“占……合计的比重”，分母是合计，不是另一项。", "hard": "360÷540≈66.7% 是只拿 B 当分母的错算。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某国货物出口 3.2 万亿美元，进口 2.6 万亿美元。", "stem": "该国 2025 年货物贸易顺差占出口额的比重约为（　）", "options": ["15.6%", "18.8%", "20.2%", "23.1%"], "answer": ["B"], "method": "顺差 = 出口−进口 = 3.2−2.6 = 0.6；占出口比重 = 0.6÷3.2≈18.75%。", "explain": "0.6÷3.2≈0.188=18.8%，选 B。", "tip": "先算顺差（0.6），再除以“出口额”3.2，别除以进口额。", "hard": "0.6÷2.6≈23.1% 是把分母当成进口额的错算，对应 D。"}, {"type": "applied", "level": "中等", "data": "【材料】某地 2025 年建成 5G 基站 18.4 万个，2020 年为 6.4 万个。", "stem": "2025 年该地基站数量比 2020 年增长约（　）", "options": ["150%", "167.5%", "187.5%", "210%"], "answer": ["C"], "method": "增长率 =（现期−基期）÷基期 =（18.4−6.4）÷6.4 = 12÷6.4 = 1.875。", "explain": "12÷6.4=1.875=187.5%，选 C。", "tip": "“增长百分之几”是相对基期，不是相对现期。", "hard": "12÷18.4≈65.2% 是把分母当成现期的错算；167.5% 是分子分母都用错的干扰项。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某市一般公共预算收入 850 亿元，其中税收收入 680 亿元，财政总收入同比增长 5%。", "stem": "2025 年该市税收收入占一般公共预算收入的比重约为（　）", "options": ["76%", "80%", "84%", "88%"], "answer": ["B"], "method": "比重 = 680÷850。850×0.8 = 680。", "explain": "680÷850=0.8=80%，选 B。", "tip": "同比增长 5% 是干扰信息；求“占比”与增速无关。", "hard": "若误用 (1+5%) 调整分子或分母，就会滑向 76% 或 84%。"}, {"type": "applied", "level": "进阶", "data": "【材料】2025 年前三季度某省社会消费品零售总额 1.5 万亿元，同比增长 4%；第四季度 0.6 万亿元，同比增长 9%。", "stem": "该省 2025 年全年社会消费品零售总额同比增速约为（　）", "options": ["4.5%", "5.4%", "6.5%", "7.0%"], "answer": ["B"], "method": "基期总量 = 1.5÷1.04 + 0.6÷1.09 ≈ 1.4423 + 0.5505 = 1.9928；现期 = 2.1。增速 = 2.1÷1.9928 − 1 ≈ 5.4%。", "explain": "2.1÷1.9928≈1.054，即增长约 5.4%，选 B。", "tip": "混合增速不能简单取平均（(4%+9%)/2=6.5% 是错的），要在基期口径下加权。", "hard": "6.5% 恰是“直接平均”的错算，对应 C，是本题最大陷阱。"}]}, {"set": 8, "date": "2026-10-05", "session": "day", "title": "资料分析速算训练 · 第 8 批（首数直除 / 增长率与增长量 / 间隔增长率 / 年均增长 / 两期比重差 / 倍数与平均数 / 化分数）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "4.27 ÷ 1.18 的商约为：", "options": ["3.0", "3.3", "3.6", "3.9"], "answer": ["C"], "method": "①先估：4.27÷1.18≈4.3÷1.2≈3.58；②用分母夹：1.18×3＝3.54，1.18×3.6＝4.248，1.18×3.7＝4.366；③被除数 4.27 落在 3.6 与 3.7 之间、更靠 3.6。", "explain": "1.18×3.6＝4.248，4.27－4.248＝0.022，0.022÷1.18≈0.019，故商≈3.619，取 3.6，选 C。", "tip": "别一上来就硬除；先确定商的整数部分（3），再用 3.6 和 3.7 夹住被除数。", "hard": "3.3 与 3.9 是常见的“估歪”结果，用分母乘 3 与 4 先定位区间可避开。"}, {"type": "pure", "level": "基础", "stem": "某指标由 250 增长到 320，增长率约为：", "options": ["28.0%", "21.9%", "12.5%", "35.2%"], "answer": ["A"], "method": "增长率＝（现期－基期）÷基期＝（320－250）÷250＝70÷250。", "explain": "70÷250＝0.28＝28.0%，选 A。", "tip": "分母一定要用“基期”（250），别用现期 320，否则会算成 21.9%（干扰项 B）。", "hard": "21.9% 正是“除以现期”的错算结果，看到选项里有它就说明命题人埋了分母坑。"}, {"type": "pure", "level": "基础", "stem": "某指标 2025 年为 480，同比增长 12.5%，则比上年增加约多少？", "options": ["60", "53", "48", "42"], "answer": ["B"], "method": "增长量＝基期×增长率＝[现期÷(1＋增长率)]×增长率。12.5%＝1/8，用“现期÷(n＋1)”速算：n＝8，增长量＝480÷9。", "explain": "480÷9≈53.3，取 53，选 B。（严格算：基期＝480÷1.125≈426.7，增长量＝426.7×0.125≈53.3。）", "tip": "增长率化分数后再算：12.5%＝1/8，增长量＝现期÷9，比先求基期再乘更快。", "hard": "干扰项 60＝480×12.5%（用现期当基期）；48＝480÷10（把 n＋1 当成 10）。"}, {"type": "pure", "level": "进阶", "stem": "某地 GDP 2024 年比 2023 年增长 8%，2025 年比 2024 年增长 5%，则 2025 年比 2023 年增长约：", "options": ["13.0%", "13.4%", "12.6%", "14.0%"], "answer": ["B"], "method": "间隔（复合）增长率 r＝r₁＋r₂＋r₁×r₂。", "explain": "r＝8%＋5%＋8%×5%＝13%＋0.4%＝13.4%，选 B。", "tip": "不能把两段增长率简单相加（8%＋5%＝13%），漏掉乘积项 r₁r₂＝0.4%。", "hard": "13.0%（干扰 A）就是漏乘的错算；增长率越大，漏乘越吃亏。"}, {"type": "pure", "level": "基础", "stem": "某指标 2019 年为 120，2024 年为 220，则 2019—2024 年的年均增长量为：", "options": ["16.7", "25", "20", "50"], "answer": ["C"], "method": "年均增长量＝（末期值－初期值）÷年份差。", "explain": "（220－120）÷（2024－2019）＝100÷5＝20，选 C。", "tip": "年份差＝2024－2019＝5，别算成 4（年份个数）或 6。", "hard": "干扰项 25＝100÷4（把年份差当年份个数），16.7＝100÷6，都是日期口径陷阱。"}, {"type": "pure", "level": "进阶", "stem": "某指标从 100 增长到 144，历时 4 年，年均增长率约为：", "options": ["9.5%", "11.0%", "12.5%", "44.0%"], "answer": ["A"], "method": "设年均增长率为 r，则 (1＋r)⁴＝144÷100＝1.44，即 1＋r＝1.44^(1/4)（开四次方）。", "explain": "1.44^(1/4)≈1.095，故 r≈9.5%，选 A。", "tip": "年均增长率要开方，不是 44%÷4＝11%；也别把总增长率直接除以年数。", "hard": "11.0%（＝44%÷4）是最典型错算；开方类题目的错项往往就卡在“除以年数”这一步。"}, {"type": "pure", "level": "进阶", "stem": "2025 年第三产业占 GDP 的比重比上年提高约多少个百分点？", "options": ["1.8", "1.2", "2.4", "3.0"], "answer": ["A"], "method": "两期比重差≈现期比重×(部分增长率－整体增长率)÷(1＋部分增长率)。", "explain": "现期比重＝2600÷5000＝52%，代入：52%×(14%－10%)÷(1＋14%)＝52%×4%÷1.14≈1.82%，选 A。（精确算：上年比重＝(2600÷1.14)÷(5000÷1.1)≈50.2%，差≈1.8 个百分点，一致。）", "tip": "只有“部分增速＞整体增速”，比重才上升；先看差值正负再定加减。", "hard": "干扰项 2.0 是把 52%×4%＝2.08% 直接当选、忘了除以 (1＋14%)。"}, {"type": "pure", "level": "基础", "stem": "A 为 3.6，B 为 0.9，则 A 是 B 的多少倍？", "options": ["2.7", "3.3", "4.0", "4.5"], "answer": ["C"], "method": "“A 是 B 的几倍”＝A÷B。", "explain": "3.6÷0.9＝4.0，选 C。", "tip": "区分“是几倍”与“多几倍”：是 4 倍，多 3 倍。", "hard": "干扰项 4.5＝3.6÷0.8（看错除数），要盯紧 B 的值。"}, {"type": "pure", "level": "基础", "stem": "某企业 2025 年产值 8.4 亿元，共有员工 3200 人，人均产值约为：", "options": ["24.5 万元", "28.1 万元", "31.2 万元", "26.3 万元"], "answer": ["D"], "method": "人均产值＝总产值÷员工数，注意单位换算：8.4 亿元＝84000 万元。", "explain": "84000÷3200＝26.25≈26.3 万元，选 D。", "tip": "亿元换算成万元要乘 10000，单位不换会差出量级。", "hard": "选项都在 25~32 万元之间，恰是“忘了单位换算”的常见区间，务必先统一单位。"}, {"type": "pure", "level": "基础", "stem": "1780 × 14.3% 的积约为：", "options": ["240", "265", "254", "278"], "answer": ["C"], "method": "化分数：14.3%≈1/7，所以原式≈1780÷7。", "explain": "1780÷7≈254.3，取 254，选 C。", "tip": "记住常用化分数：1/7≈14.3%、1/6≈16.7%、1/8＝12.5%、1/9≈11.1%。", "hard": "14.3% 若换成 1/6（16.7%）会得到 297，明显偏大；换分数要换对。"}, {"type": "pure", "level": "进阶", "stem": "某值先增长 15%，再下降 10%，最终比原值变化约：", "options": ["＋3.5%", "＋5.0%", "－5.0%", "＋25.0%"], "answer": ["A"], "method": "复合计算：1×(1＋15%)×(1－10%)＝1×1.15×0.90。", "explain": "1.15×0.90＝1.035，即最终比原值高 3.5%，选 A。", "tip": "“先涨后跌”不能直接相减（15%－10%＝5%），必须乘起来。", "hard": "干扰项 ＋5.0% 正是直接相减的结果；涨跌幅接近时，差得不多但方向可能相反。"}, {"type": "pure", "level": "基础", "stem": "3.14 × 6.28 的积约为：", "options": ["15.8", "17.5", "19.7", "21.2"], "answer": ["C"], "method": "估算夹逼：3.14×6＝18.84，3.14×6.3≈19.78。", "explain": "3.14×6.28≈19.72，取 19.7，选 C。", "tip": "先用整数部分卡范围，再取中间值，比硬算快。", "hard": "17.5 是“把 6.28 当成 5.6”的错算，21.2 是“当成 6.8”，都要靠夹逼排除。"}, {"type": "applied", "level": "基础", "stem": "2024 年该市规模以上工业增加值约为多少亿元？", "data": "【材料】2025 年某市规模以上工业增加值 2450 亿元，比上年增长 9.2%。", "options": ["2244", "2210", "2270", "2300"], "answer": ["A"], "method": "基期量＝现期量÷(1＋增长率)。", "explain": "2450÷(1＋9.2%)＝2450÷1.092≈2243.6，取 2244，选 A。", "tip": "求基期用“除以 (1＋增长率)”，别用“现期×(1－9.2%)”，那是错的。", "hard": "2450×(1－9.2%)≈2225，会滑向 2210 附近；记住求基期只能除不能减。"}, {"type": "applied", "level": "基础", "stem": "2025 年该省游客人均旅游消费约为多少元？", "data": "【材料】2025 年某省接待游客 3.6 亿人次，同比增长 18.5%；实现旅游收入 4200 亿元，同比增长 22.4%。", "options": ["1050", "1280", "980", "1167"], "answer": ["D"], "method": "人均消费＝旅游收入÷游客人次，注意单位：亿元÷亿人次＝元/人次。", "explain": "4200÷3.6≈1166.7，取 1167，选 D。", "tip": "两个量都以“亿”为单位，可先约掉“亿”再算，避免单位出错。", "hard": "用上年数据反算会跑偏；题目问的是“2025 年人均消费”，直接取现期相除。"}, {"type": "applied", "level": "基础", "stem": "2024 年 1—9 月该公司营业收入约为多少亿元？", "data": "【材料】2025 年 1—9 月，某公司营业收入 186 亿元，同比增长 12%；其中第三季度营业收入 70 亿元，同比增长 16%。", "options": ["156", "166", "164", "178"], "answer": ["B"], "method": "本问的“1—9 月”整体只对应总量 186 亿元、增速 12%，用基期公式即可。", "explain": "186÷1.12≈166.1，取 166，选 B。", "tip": "“其中第三季度……”是干扰信息，与本问无关；先看清问的是“1—9 月”。", "hard": "用 16% 或把 70 亿元混进来算，都会滑向错误选项；要锁定“总量＋对应增速”。"}, {"type": "applied", "level": "基础", "stem": "2025 年某县农村居民人均可支配收入比 2024 年增长约百分之几？", "data": "【材料】2024 年某县农村居民人均可支配收入 18500 元，2025 年为 20800 元。", "options": ["10.8%", "11.1%", "12.4%", "13.5%"], "answer": ["C"], "method": "增长率＝(现期－基期)÷基期。", "explain": "(20800－18500)÷18500＝2300÷18500≈12.4%，选 C。", "tip": "分母用基期 18500，别除以 20800。", "hard": "2300÷20800≈11.1%（干扰 B）就是“除以现期”的错算，要看清分母。"}, {"type": "applied", "level": "进阶", "stem": "2025 年该地区进出口总额比上年增长约百分之几？", "data": "【材料】某地区 2025 年货物进口额 3200 亿美元，同比下降 8%；出口额 4500 亿美元，同比增长 6%。", "options": ["－0.3%", "＋1.0%", "－1.5%", "＋2.5%"], "answer": ["A"], "method": "先分别求上年进出口额，再加总求增长率。上年进口＝3200÷0.92，上年出口＝4500÷1.06。", "explain": "上年进口≈3478.3、上年出口≈4245.3，合计≈7723.6；今年合计＝3200＋4500＝7700。(7700－7723.6)÷7723.6≈－0.31%，选 A。", "tip": "进出口一增一减，要先把基期分别还原再加总，不能把 ＋6% 与 －8% 直接平均。", "hard": "两段方向相反时，总额增速可能很小甚至为负，容易被“大概在中间”的直觉带偏。"}, {"type": "applied", "level": "进阶", "stem": "2019—2025 年该市快递业务量的年均增长率约为多少？", "data": "【材料】2025 年某市快递业务量 12.6 亿件，同比增长 25%；2019 年为 5.6 亿件。", "options": ["12.0%", "18.0%", "14.5%", "22.5%"], "answer": ["C"], "method": "倍数＝12.6÷5.6＝2.25，年份差＝2025－2019＝6，令 (1＋r)⁶＝2.25，开六次方。", "explain": "1＋r＝2.25^(1/6)≈1.145，故 r≈14.5%，选 C。", "tip": "只用到初期、末期值，中间的 25% 是干扰；年均增长率一定要开方。", "hard": "6 年翻 2.25 倍，年均约 14.5%；若误除以年数会得到 20% 以上，滑向 22.5%。"}, {"type": "applied", "level": "进阶", "stem": "2024 年该省规模以上工业总产值约为多少亿元？", "data": "【材料】2025 年某省高新技术产业产值 5600 亿元，占规模以上工业总产值的 32%，同比增长 12%；2024 年该比重为 29%。", "options": ["17500", "17241", "17000", "16800"], "answer": ["B"], "method": "①先求 2024 年高新技术产业产值：5600÷1.12；②再用 2024 年的比重 29% 反推总产值。", "explain": "5600÷1.12＝5000；5000÷0.29≈17241，选 B。", "tip": "反推总产值要用“对应年份的比重”：2024 年产值配 29%，不能拿 2025 年的 32% 去除 2024 年的产值。", "hard": "5600÷0.32＝17500（干扰 A）是“用现期产值除现期比重”，错在年份错配。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市社会消费品零售总额约为多少亿元？", "data": "【材料】2025 年某市限额以上单位网上零售额 860 亿元，占社会消费品零售总额的 21.5%；2024 年网上零售额为 700 亿元，占比 19.2%。", "options": ["4000", "4050", "3900", "3800"], "answer": ["A"], "method": "整体量＝部分量÷部分所占比重，取现期数据：860÷21.5%。", "explain": "860÷0.215＝4000，选 A。", "tip": "用现期（2025 年）的网上零售额配现期比重 21.5%，不要误用 2024 年的 19.2%。", "hard": "860÷0.192≈4479（不在选项）会把人绕晕；先锁定“年份—数据”对应关系再算。"}]}];
